function estadoRango(valor, key) {
  const r = RANGOS_ANTROPOMETRIA[key];
  if (!r || valor === undefined || valor === null || valor === "") return null;
  const v = Number(valor);
  if (v < r.min) return { label: "Bajo", color: "#2F80ED" };
  if (v > r.max) return { label: "Alto", color: T.accent2 };
  return { label: "Normal", color: "#3F9142" };
}

