/** Hook simple para detectar pantallas angostas (tablet/celular) y adaptar el layout */
function useIsNarrow(breakpoint = 1000) {
  const [narrow, setNarrow] = useState(() => (typeof window !== "undefined" ? window.innerWidth < breakpoint : false));
  useEffect(() => {
    const onResize = () => setNarrow(window.innerWidth < breakpoint);
    window.addEventListener("resize", onResize);
    onResize();
    return () => window.removeEventListener("resize", onResize);
  }, [breakpoint]);
  return narrow;
}

function interpolarPlantilla(texto, vars) {
  return (texto || "").replace(/\{(\w+)\}/g, (_, key) => (vars[key] !== undefined && vars[key] !== null ? vars[key] : ""));
}

/* ---------------------------------------------------------
   Modo demo / activación
--------------------------------------------------------- */
const DIAS_PRUEBA = 14;
const LIMITE_PACIENTES_DEMO = 3;

/** Código determinístico: dado el usuario, cualquiera que conozca esta fórmula puede generarlo (tú, para dárselo a tus clientes) */
function generarCodigoActivacion(username) {
  const str = `NUTRYEASY-${(username || "").toLowerCase()}-2026`;
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
  return String((hash % 900000) + 100000);
}

function estadoPlan(user) {
  if (user?.planActivo) return { activo: true, diasRestantes: null, expirado: false };
  const inicio = user?.fechaRegistro ? new Date(user.fechaRegistro) : new Date();
  const dias = Math.floor((Date.now() - inicio.getTime()) / (1000 * 60 * 60 * 24));
  const diasRestantes = DIAS_PRUEBA - dias;
  return { activo: false, diasRestantes, expirado: diasRestantes <= 0 };
}

/** % de cambio respecto al mes anterior, redondeado; null si no hay base para comparar */
function calcDelta(actual, anterior) {
  if (anterior === undefined || anterior === null) return null;
  if (anterior === 0) return actual > 0 ? 100 : 0;
  return Math.round(((actual - anterior) / anterior) * 100);
}
const normName = (n) => (n || "").trim().toLowerCase().replace(/\s+/g, " ");

/** Busca un paciente ya existente por teléfono o por nombre completo (para detectar duplicados) */
async function buscarPacienteExistente({ telefono, nombre }) {
  const users = (await sGet("users")) || {};
  const telKey = normPhone(telefono);
  if (telKey && users[telKey] && users[telKey].role === "paciente") {
    return { username: telKey, ...users[telKey] };
  }
  const nameKey = normName(nombre);
  if (nameKey) {
    const entry = Object.entries(users).find(([, v]) => v.role === "paciente" && normName(v.name) === nameKey);
    if (entry) return { username: entry[0], ...entry[1] };
  }
  return null;
}

/** Vincula un paciente ya existente (de otro nutriólogo) a este nutriólogo, copiando su expediente como punto de partida independiente */
async function vincularPacienteExistente(patientUsername, nutriUsername) {
  const users = (await sGet("users")) || {};
  const p = users[patientUsername];
  if (!p) return;
  const nutriologos = Array.from(new Set([...(p.nutriologos || []), nutriUsername]));
  const prevActual = p.nutriologoActual;
  users[patientUsername] = { ...p, nutriologos, nutriologoActual: nutriUsername };
  await sSet("users", users);

  if (prevActual && prevActual !== nutriUsername) {
    const prevExp = await sGet(`expediente:${prevActual}:${patientUsername}`);
    if (prevExp) await sSet(`expediente:${nutriUsername}:${patientUsername}`, prevExp);
  }

  const list = (await sGet(`patients:${nutriUsername}`)) || [];
  if (!list.includes(patientUsername)) {
    list.push(patientUsername);
    await sSet(`patients:${nutriUsername}`, list);
  }
}

/** Crea un paciente nuevo, sin contraseña, pendiente de que él mismo la active con su teléfono */
async function crearPacientePendiente({ nombre, telefono }, nutriUsername) {
  const telKey = normPhone(telefono);
  const users = (await sGet("users")) || {};
  users[telKey] = {
    password: null, role: "paciente", name: nombre.trim(), telefono: telKey,
    nutriologos: [nutriUsername], nutriologoActual: nutriUsername, activo: false,
  };
  await sSet("users", users);
  const list = (await sGet(`patients:${nutriUsername}`)) || [];
  if (!list.includes(telKey)) {
    list.push(telKey);
    await sSet(`patients:${nutriUsername}`, list);
  }
  return telKey;
}

/* ---------------------------------------------------------
   Ring chart — signature element
--------------------------------------------------------- */
function IMCPanel({ imc }) {
  const cat = imcCategoria(imc);
  return (
    <>
      <div style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: 36, fontWeight: 600, color: cat ? cat.color : T.brand }}>
        {imc || "—"}
      </div>
      <div style={{ fontSize: 12, color: T.inkSoft, marginBottom: 10 }}>kg/m²</div>

      {cat && (
        <span style={{
          display: "inline-block", fontSize: 12, fontWeight: 700, color: "#fff",
          background: cat.color, padding: "3px 12px", borderRadius: 999, marginBottom: 16,
        }}>
          {cat.label}
        </span>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 20 }}>
        {IMC_RANGOS.map((r) => {
          const activo = cat && cat.label === r.label;
          return (
            <div
              key={r.label}
              style={{
                display: "flex", justifyContent: "space-between", alignItems: "center",
                padding: "5px 8px", borderRadius: 6,
                background: activo ? `${r.color}1A` : "transparent",
                border: `1px solid ${activo ? r.color : "transparent"}`,
              }}
            >
              <span style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: activo ? 700 : 500, color: T.ink }}>
                <span style={{ width: 8, height: 8, borderRadius: "50%", background: r.color, display: "inline-block", flexShrink: 0 }} />
                {r.label}
              </span>
              <span style={{ fontSize: 11, fontFamily: "IBM Plex Mono, monospace", color: T.inkSoft }}>{r.rango}</span>
            </div>
          );
        })}
      </div>
    </>
  );
}

function PlateRing({ data, size = 120, thickness = 14 }) {
  const total = data.reduce((s, d) => s + d.value, 0) || 1;
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  let offset = 0;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#E4E9DF" strokeWidth={thickness} />
      {data.map((d) => {
        const frac = d.value / total;
        const dash = frac * c;
        const el = (
          <circle
            key={d.key}
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke={d.color}
            strokeWidth={thickness}
            strokeDasharray={`${dash} ${c - dash}`}
            strokeDashoffset={-offset}
            strokeLinecap="butt"
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        );
        offset += dash;
        return el;
      })}
    </svg>
  );
}

function resizeImageToDataUrl(file, maxSize) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        if (w > h) { if (w > maxSize) { h = Math.round((h * maxSize) / w); w = maxSize; } }
        else if (h > maxSize) { w = Math.round((w * maxSize) / h); h = maxSize; }
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", 0.82));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

/** Avatar de paciente con foto real (subida por el nutriólogo); si no hay foto, cae a un círculo con la inicial. */
function PatientAvatar({ username, name, size = 40, editable = false }) {
  const [foto, setFoto] = useState(null);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef(null);

  const load = useCallback(async () => {
    if (!username) return;
    const f = await sGet(`fotoPaciente:${username}`);
    setFoto(f || null);
  }, [username]);
  useEffect(() => { load(); }, [load]);

  const onFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    try {
      const dataUrl = await resizeImageToDataUrl(file, 320);
      await sSet(`fotoPaciente:${username}`, dataUrl);
      setFoto(dataUrl);
    } finally {
      setLoading(false);
      e.target.value = "";
    }
  };

  return (
    <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
      {foto ? (
        <img src={foto} alt={name} style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", display: "block" }} />
      ) : (
        <div style={{
          width: size, height: size, borderRadius: "50%", background: "#EAF2ED",
          display: "flex", alignItems: "center", justifyContent: "center", color: T.brand, fontWeight: 700,
          fontSize: size * 0.4, flexShrink: 0,
        }}>
          {(name || "?").charAt(0).toUpperCase()}
        </div>
      )}
      {editable && (
        <>
          <button
            onClick={() => inputRef.current?.click()}
            title="Cambiar foto"
            style={{
              position: "absolute", bottom: -2, right: -2, width: Math.max(20, size * 0.34), height: Math.max(20, size * 0.34),
              borderRadius: "50%", background: T.brand, border: "2px solid #fff", display: "flex",
              alignItems: "center", justifyContent: "center", cursor: "pointer", color: "#fff", padding: 0,
            }}
          >
            <Camera size={Math.max(10, size * 0.16)} />
          </button>
          <input ref={inputRef} type="file" accept="image/*" onChange={onFile} style={{ display: "none" }} />
        </>
      )}
      {loading && <div style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "rgba(255,255,255,0.65)" }} />}
    </div>
  );
}

/** Medidor semicircular tipo velocímetro, de 0 a 100 */
function GaugeArc({ value, size = 180 }) {
  const w = size, h = size / 2 + 20;
  const r = size / 2 - 14;
  const cx = size / 2, cy = size / 2 + 6;
  const angle = Math.PI * (1 - Math.min(100, Math.max(0, value)) / 100);
  const x = cx + r * Math.cos(angle);
  const y = cy - r * Math.sin(angle);
  const bg = "#E4E9DF";
  const color = value >= 70 ? "#3F9142" : value >= 40 ? T.accent : T.accent2;
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`}>
      <path d={`M ${cx - r} ${cy} A ${r} ${r} 0 0 1 ${cx + r} ${cy}`} fill="none" stroke={bg} strokeWidth={14} strokeLinecap="round" />
      <path
        d={`M ${cx - r} ${cy} A ${r} ${r} 0 0 1 ${x} ${y}`}
        fill="none" stroke={color} strokeWidth={14} strokeLinecap="round"
      />
      <text x={cx} y={cy - 6} textAnchor="middle" fontSize={size * 0.2} fontWeight={700} fontFamily="IBM Plex Mono, monospace" fill={T.ink}>
        {value}
      </text>
      <text x={cx + size * 0.14} y={cy - 6} fontSize={11} fill={T.inkSoft}>/100</text>
    </svg>
  );
}

function ProgressRing({ percent, size = 110, thickness = 12, color = T.brand, label }) {
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  const dash = (Math.min(100, Math.max(0, percent)) / 100) * c;
  return (
    <div style={{ position: "relative", width: size, height: size, margin: "0 auto" }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#E4E9DF" strokeWidth={thickness} />
        <circle
          cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={thickness}
          strokeDasharray={`${dash} ${c - dash}`} strokeLinecap="round"
          transform={`rotate(-90 ${size / 2} ${size / 2})`}
        />
      </svg>
      <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: size * 0.24, fontWeight: 700, color: T.ink }}>{percent}%</span>
        {label && <span style={{ fontSize: 10, color: T.inkSoft }}>{label}</span>}
      </div>
    </div>
  );
}

