/* ---------------------------------------------------------
   Nutriólogo: lista de pacientes
--------------------------------------------------------- */
function NuevoPacienteForm({ user, onDone }) {
  const [form, setForm] = useState({ nombre: "", telefono: "" });
  const [match, setMatch] = useState(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const buscar = async () => {
    setError("");
    if (!form.nombre.trim() || !form.telefono.trim()) {
      setError("Escribe el nombre completo y el teléfono del paciente.");
      return;
    }
    if (normPhone(form.telefono).length < 10) {
      setError("Escribe un número de teléfono válido (10 dígitos).");
      return;
    }
    if (!user.planActivo) {
      const actuales = (await sGet(`patients:${user.username}`)) || [];
      if (actuales.length >= LIMITE_PACIENTES_DEMO) {
        setError(`El modo demo permite hasta ${LIMITE_PACIENTES_DEMO} pacientes. Activa tu cuenta en Configuración para agregar más.`);
        return;
      }
    }
    setBusy(true);
    const encontrado = await buscarPacienteExistente({ telefono: form.telefono, nombre: form.nombre });
    setBusy(false);

    if (encontrado && (encontrado.nutriologos || []).includes(user.username)) {
      setError("Este paciente ya está en tu lista.");
      return;
    }
    if (encontrado) {
      setMatch(encontrado);
      return;
    }
    setBusy(true);
    await crearPacientePendiente(form, user.username);
    setBusy(false);
    onDone();
  };

  const confirmarVinculo = async () => {
    setBusy(true);
    await vincularPacienteExistente(match.username, user.username);
    setBusy(false);
    onDone();
  };

  return (
    <Card style={{ marginBottom: 20, maxWidth: 460 }}>
      {match ? (
        <div>
          <div style={{ display: "flex", gap: 10, alignItems: "flex-start", marginBottom: 16 }}>
            <div style={{ width: 34, height: 34, borderRadius: "50%", background: "#FDF1E0", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
              <Users size={16} color={T.accent} />
            </div>
            <div style={{ fontSize: 14, color: T.ink, lineHeight: 1.5 }}>
              <strong>{match.name}</strong> ya está registrado con otro nutriólogo.
              ¿Deseas vincularlo a tu lista y traer una copia de su expediente para continuar tú el seguimiento?
            </div>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <Button onClick={confirmarVinculo} disabled={busy}>{busy ? "Un momento…" : "Sí, vincular y traer expediente"}</Button>
            <Button variant="ghost" onClick={() => { setMatch(null); setForm({ nombre: "", telefono: "" }); }}>Cancelar</Button>
          </div>
        </div>
      ) : (
        <>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Registrar nuevo paciente</div>
          <Field label="Nombre completo">
            <input style={inputStyle} value={form.nombre} onChange={(e) => setForm({ ...form, nombre: e.target.value })} placeholder="Ej. Kevin Mundo" />
          </Field>
          <Field label="Número de teléfono">
            <input style={inputStyle} value={form.telefono} onChange={(e) => setForm({ ...form, telefono: e.target.value })} placeholder="10 dígitos, ej. 6461234567" />
          </Field>
          <p style={{ fontSize: 12, color: T.inkSoft, marginTop: -8, marginBottom: 14, lineHeight: 1.5 }}>
            El paciente usará este teléfono para activar su cuenta y crear su propia contraseña la primera vez que entre.
          </p>
          {error && <div style={{ color: T.accent2, fontSize: 13, marginBottom: 12, fontWeight: 500 }}>{error}</div>}
          <div style={{ display: "flex", gap: 8 }}>
            <Button onClick={buscar} disabled={busy}>{busy ? "Un momento…" : "Registrar paciente"}</Button>
            <Button variant="ghost" onClick={onDone}>Cancelar</Button>
          </div>
        </>
      )}
    </Card>
  );
}

function PatientList({ user, onOpen, busqueda, setBusqueda, abrirFormExterno }) {
  const [patients, setPatients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);
  const [editName, setEditName] = useState("");
  const [confirmRemove, setConfirmRemove] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    const list = (await sGet(`patients:${user.username}`)) || [];
    const users = (await sGet("users")) || {};
    setPatients(list.map((u) => ({ username: u, name: users[u]?.name || u, activo: users[u]?.activo !== false })));
    setLoading(false);
  }, [user.username]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    if (abrirFormExterno) setShowForm(true);
  }, [abrirFormExterno]);

  const guardarNombre = async (username) => {
    if (!editName.trim()) return;
    const users = (await sGet("users")) || {};
    if (users[username]) {
      users[username] = { ...users[username], name: editName.trim() };
      await sSet("users", users);
    }
    setEditing(null);
    load();
  };

  const darDeBaja = async (username) => {
    const users = (await sGet("users")) || {};
    const p = users[username];
    if (p) {
      const restantes = (p.nutriologos || []).filter((n) => n !== user.username);
      users[username] = {
        ...p,
        nutriologos: restantes,
        nutriologoActual: p.nutriologoActual === user.username ? (restantes[0] || null) : p.nutriologoActual,
      };
      await sSet("users", users);
    }
    const list = (await sGet(`patients:${user.username}`)) || [];
    await sSet(`patients:${user.username}`, list.filter((u) => u !== username));
    setConfirmRemove(null);
    load();
  };

  const exportarExcel = () => {
    const filas = patients.map((p) => ({
      Nombre: p.name,
      Teléfono: formatPhone(p.username),
      Estado: p.activo ? "Activo" : "Pendiente de activación",
    }));
    const ws = XLSX.utils.json_to_sheet(filas);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Pacientes");
    XLSX.writeFile(wb, `pacientes_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  const filtrados = patients.filter((p) =>
    p.name.toLowerCase().includes(busqueda.toLowerCase()) || formatPhone(p.username).includes(busqueda)
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 24, gap: 16, flexWrap: "wrap" }}>
        <div>
          <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 30, margin: 0, color: T.ink }}>Tus pacientes</h1>
          <p style={{ color: T.inkSoft, marginTop: 6 }}>
            Regístralos tú mismo, o comparte tu usuario (<code style={{ background: T.bg, padding: "2px 6px", borderRadius: 4 }}>{user.username}</code>) para que se registren ellos.
          </p>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {patients.length > 0 && (
            <Button variant="ghost" onClick={exportarExcel}><FileDown size={15} /> Exportar Excel</Button>
          )}
          {!showForm && <Button onClick={() => setShowForm(true)}><Plus size={15} /> Nuevo paciente</Button>}
        </div>
      </div>

      {showForm && <NuevoPacienteForm user={user} onDone={() => { setShowForm(false); load(); }} />}

      {patients.length > 0 && (
        <div style={{ marginBottom: 16, maxWidth: 320 }}>
          <input
            style={inputStyle}
            placeholder="Buscar por nombre o teléfono…"
            value={busqueda}
            onChange={(e) => setBusqueda(e.target.value)}
          />
        </div>
      )}

      {loading ? (
        <div style={{ color: T.inkSoft }}>Cargando…</div>
      ) : patients.length === 0 ? (
        <Card style={{ textAlign: "center", padding: 40 }}>
          <Users size={28} color={T.brandLight} style={{ marginBottom: 10 }} />
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 18, marginBottom: 4 }}>Aún no tienes pacientes</div>
          <div style={{ color: T.inkSoft, fontSize: 14 }}>Regístralos con el botón de arriba, o espera a que se registren ellos con tu usuario.</div>
        </Card>
      ) : filtrados.length === 0 ? (
        <div style={{ color: T.inkSoft, fontSize: 14 }}>Sin resultados para "{busqueda}".</div>
      ) : (
        <div style={{ display: "grid", gap: 10, gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))" }}>
          {filtrados.map((p) => (
            <div
              key={p.username}
              style={{
                padding: 16, borderRadius: 12, border: `1px solid ${T.line}`,
                background: T.surface, fontFamily: "Inter, sans-serif",
              }}
            >
              {editing === p.username ? (
                <div>
                  <input
                    style={{ ...inputStyle, marginBottom: 8 }}
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    autoFocus
                  />
                  <div style={{ display: "flex", gap: 6 }}>
                    <Button onClick={() => guardarNombre(p.username)} style={{ padding: "6px 12px", fontSize: 13 }}>Guardar</Button>
                    <Button variant="ghost" onClick={() => setEditing(null)} style={{ padding: "6px 12px", fontSize: 13 }}>Cancelar</Button>
                  </div>
                </div>
              ) : confirmRemove === p.username ? (
                <div>
                  <div style={{ fontSize: 13, color: T.ink, marginBottom: 10 }}>¿Dar de baja a <strong>{p.name}</strong>? No se borra su expediente, solo deja de aparecer en tu lista.</div>
                  <div style={{ display: "flex", gap: 6 }}>
                    <Button variant="danger" onClick={() => darDeBaja(p.username)} style={{ padding: "6px 12px", fontSize: 13 }}>Sí, dar de baja</Button>
                    <Button variant="ghost" onClick={() => setConfirmRemove(null)} style={{ padding: "6px 12px", fontSize: 13 }}>Cancelar</Button>
                  </div>
                </div>
              ) : (
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                  <button
                    onClick={() => onOpen(p.username)}
                    style={{ display: "flex", alignItems: "center", gap: 12, background: "none", border: "none", cursor: "pointer", textAlign: "left", flex: 1, minWidth: 0, padding: 0 }}
                  >
                    <PatientAvatar username={p.username} name={p.name} size={36} />
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontWeight: 600, color: T.ink, fontSize: 14, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.name}</div>
                      {p.activo ? (
                        <div style={{ fontSize: 12, color: T.inkSoft, fontFamily: "IBM Plex Mono, monospace" }}>{formatPhone(p.username)}</div>
                      ) : (
                        <div style={{ fontSize: 11, color: T.accent, fontWeight: 700 }}>Pendiente de activación</div>
                      )}
                    </div>
                  </button>
                  <div style={{ display: "flex", alignItems: "center", gap: 4, flexShrink: 0 }}>
                    {p.activo && (
                      <a
                        href={waLink(p.username, `Hola ${p.name.split(" ")[0]}, te escribo de NutryEasy para tu seguimiento nutricional. 🥗`)}
                        target="_blank" rel="noopener noreferrer"
                        onClick={(e) => e.stopPropagation()}
                        title="Escribir por WhatsApp"
                        style={{ display: "flex", color: "#25D366", padding: 6 }}
                      >
                        <MessageCircle size={14} />
                      </a>
                    )}
                    <button onClick={() => { setEditing(p.username); setEditName(p.name); }} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft, padding: 6 }} aria-label="Editar">
                      <Pencil size={14} />
                    </button>
                    <button onClick={() => setConfirmRemove(p.username)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft, padding: 6 }} aria-label="Dar de baja">
                      <UserX size={14} />
                    </button>
                    <ChevronRight size={16} color={T.inkSoft} />
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Nutriólogo: detalle de paciente (Expediente + Dietocálculo)
--------------------------------------------------------- */
function PatientDetail({ patientUsername, onBack, nutriUser, initialTab, onTabChange }) {
  const narrow = useIsNarrow(1180);
  const [tab, setTabInternal] = useState(initialTab || "expediente");
  const setTab = (k) => { setTabInternal(k); onTabChange && onTabChange(k); };
  useEffect(() => { if (initialTab) setTabInternal(initialTab); }, [initialTab]);
  const [name, setName] = useState(patientUsername);
  const [exp, setExp] = useState({ edad: "", sexo: "M", peso: "", talla: "", notas: "", historial: [] });
  const [bitacora, setBitacora] = useState([]);
  const [nuevaNotaBitacora, setNuevaNotaBitacora] = useState("");
  const [dieta, setDieta] = useState({ calorias: 2000, proteinas: 25, carbohidratos: 45, grasas: 30, comidas: [] });
  const [nuevoAlimento, setNuevoAlimento] = useState({ grupo: "verduras", nombre: "", comida: "Desayuno" });
  const [saved, setSaved] = useState(false);
  const [plantillas, setPlantillas] = useState(PLANTILLAS_DEFAULT);
  const [habitos, setHabitos] = useState([]);
  const [nuevoHabito, setNuevoHabito] = useState("");
  const [habitosLog, setHabitosLog] = useState({});
  const [bancoAlimentos, setBancoAlimentos] = useState([]);
  const [preguntasCuestionario, setPreguntasCuestionario] = useState([]);
  const [respuestasCuestionario, setRespuestasCuestionario] = useState({});
  const [savedCuestionario, setSavedCuestionario] = useState(false);
  const [editingCards, setEditingCards] = useState(() => new Set());
  const [fotosProgreso, setFotosProgreso] = useState([]);
  const [subiendoFoto, setSubiendoFoto] = useState(false);
  const [subvistaAntro, setSubvistaAntro] = useState("mediciones");
  const [editandoMedidas, setEditandoMedidas] = useState(false);

  useEffect(() => {
    (async () => {
      const users = (await sGet("users")) || {};
      if (users[patientUsername]) setName(users[patientUsername].name);
      const e = await sGet(`expediente:${nutriUser.username}:${patientUsername}`);
      if (e) setExp(e);
      const d = await sGet(`dieta:${patientUsername}`);
      if (d) setDieta(d);
      const cat = await sGet(`dietasPredisenadas:${nutriUser.username}`);
      if (cat && cat.length) setPlantillas(cat);
      const h = await sGet(`habitos:${patientUsername}`);
      setHabitos(h || []);
      const log = await sGet(`habitosLog:${patientUsername}`);
      setHabitosLog(log || {});
      const bit = await sGet(`bitacora:${nutriUser.username}:${patientUsername}`);
      setBitacora(bit || []);
      const banco = await sGet(`alimentos:${nutriUser.username}`);
      setBancoAlimentos(banco || []);
      const preg = await sGet(`cuestionario:${nutriUser.username}`);
      setPreguntasCuestionario(preg && preg.length ? preg : CUESTIONARIO_DEFAULT);
      const resp = await sGet(`cuestionarioRespuestas:${nutriUser.username}:${patientUsername}`);
      setRespuestasCuestionario(resp || {});
      const fotos = await sGet(`fotosProgreso:${nutriUser.username}:${patientUsername}`);
      setFotosProgreso(fotos || []);
    })();
  }, [patientUsername]);

  const guardarCuestionario = async () => {
    await sSet(`cuestionarioRespuestas:${nutriUser.username}:${patientUsername}`, respuestasCuestionario);
    setSavedCuestionario(true);
    setTimeout(() => setSavedCuestionario(false), 1600);
  };

  const addNotaBitacora = async () => {
    if (!nuevaNotaBitacora.trim()) return;
    const entry = { id: Date.now(), texto: nuevaNotaBitacora.trim(), fecha: new Date().toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" }) };
    const updated = [entry, ...bitacora];
    setBitacora(updated);
    setNuevaNotaBitacora("");
    await sSet(`bitacora:${nutriUser.username}:${patientUsername}`, updated);
  };

  const removeNotaBitacora = async (id) => {
    const updated = bitacora.filter((n) => n.id !== id);
    setBitacora(updated);
    await sSet(`bitacora:${nutriUser.username}:${patientUsername}`, updated);
  };

  const addHabito = async () => {
    if (!nuevoHabito.trim()) return;
    const updated = [...habitos, { id: Date.now(), texto: nuevoHabito.trim() }];
    setHabitos(updated);
    setNuevoHabito("");
    await sSet(`habitos:${patientUsername}`, updated);
  };

  const removeHabito = async (id) => {
    const updated = habitos.filter((h) => h.id !== id);
    setHabitos(updated);
    await sSet(`habitos:${patientUsername}`, updated);
  };

  const imc = exp.peso && exp.talla ? (exp.peso / ((exp.talla / 100) ** 2)).toFixed(1) : null;

  const saveExpediente = async () => {
    const historial = [...(exp.historial || [])];
    if (exp.peso) {
      const today = new Date().toISOString().slice(0, 10);
      const filtered = historial.filter((h) => h.fecha !== today);
      filtered.push({ fecha: today, peso: Number(exp.peso), grasa: exp.porcentajeGrasa ? Number(exp.porcentajeGrasa) : null });
      await sSet(`expediente:${nutriUser.username}:${patientUsername}`, { ...exp, historial: filtered });
      setExp((prev) => ({ ...prev, historial: filtered }));
    } else {
      await sSet(`expediente:${nutriUser.username}:${patientUsername}`, exp);
    }
    flashSaved();
  };

  const toggleEditCard = (id) => {
    setEditingCards((prev) => {
      const next = new Set(prev);
      if (next.has(id)) { next.delete(id); saveExpediente(); } else { next.add(id); }
      return next;
    });
  };

  const subirFotoProgreso = async (file, angulo) => {
    if (!file) return;
    setSubiendoFoto(true);
    try {
      const dataUrl = await resizeImageToDataUrl(file, 500);
      const entry = { id: Date.now(), fecha: new Date().toISOString().slice(0, 10), angulo, foto: dataUrl };
      const updated = [entry, ...fotosProgreso];
      setFotosProgreso(updated);
      await sSet(`fotosProgreso:${nutriUser.username}:${patientUsername}`, updated);
    } finally {
      setSubiendoFoto(false);
    }
  };

  const eliminarFotoProgreso = async (id) => {
    const updated = fotosProgreso.filter((f) => f.id !== id);
    setFotosProgreso(updated);
    await sSet(`fotosProgreso:${nutriUser.username}:${patientUsername}`, updated);
  };

  const flashSaved = () => {
    setSaved(true);
    setTimeout(() => setSaved(false), 1600);
  };

  const macroGrams = () => {
    const kcal = Number(dieta.calorias) || 0;
    return {
      proteinas: Math.round((kcal * (dieta.proteinas / 100)) / 4),
      carbohidratos: Math.round((kcal * (dieta.carbohidratos / 100)) / 4),
      grasas: Math.round((kcal * (dieta.grasas / 100)) / 9),
    };
  };

  const saveDieta = async () => {
    const conFecha = dieta.fechaAsignada ? dieta : { ...dieta, fechaAsignada: new Date().toISOString().slice(0, 10) };
    setDieta(conFecha);
    await sSet(`dieta:${patientUsername}`, conFecha);
    flashSaved();
  };

  const addAlimento = () => {
    if (!nuevoAlimento.nombre.trim()) return;
    setDieta((d) => ({ ...d, comidas: [...d.comidas, { ...nuevoAlimento, id: Date.now() }] }));
    const yaExiste = bancoAlimentos.some((a) => a.nombre.toLowerCase() === nuevoAlimento.nombre.trim().toLowerCase());
    if (!yaExiste) {
      const updatedBanco = [...bancoAlimentos, { id: Date.now(), nombre: nuevoAlimento.nombre.trim(), grupo: nuevoAlimento.grupo }];
      setBancoAlimentos(updatedBanco);
      sSet(`alimentos:${nutriUser.username}`, updatedBanco);
    }
    setNuevoAlimento({ ...nuevoAlimento, nombre: "" });
  };

  const removeAlimento = (id) => {
    setDieta((d) => ({ ...d, comidas: d.comidas.filter((c) => c.id !== id) }));
  };

  const grams = macroGrams();
  const ringData = GROUPS.filter((g) => ["proteinas", "carbohidratos", "grasas"].includes(g.key) || true).map((g) => {
    const map = { proteinas: dieta.proteinas, carbohidratos: dieta.carbohidratos, grasas: dieta.grasas };
    return { ...g, value: map[g.key] ?? 0 };
  }).filter((g) => ["proteinas", "carbohidratos", "grasas"].includes(g.key));

  return (
    <div>
      <button onClick={onBack} style={{ background: "none", border: "none", color: T.brand, cursor: "pointer", fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 13, marginBottom: 14, padding: 0 }}>
        ← Volver a pacientes
      </button>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 20 }}>
        <PatientAvatar username={patientUsername} name={name} size={56} editable />
        <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: 0, color: T.ink }}>{name}</h1>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 20, borderBottom: `1px solid ${T.line}` }}>
        {[
          { k: "expediente", label: "Expediente", icon: ClipboardList },
          { k: "antropometria", label: "Antropometría", icon: Ruler },
          { k: "cuestionario", label: "Cuestionario", icon: FlaskConical },
          { k: "bitacora", label: "Bitácora", icon: Pencil },
          { k: "dieta", label: "Dietocálculo", icon: Utensils },
          { k: "habitos", label: "Hábitos", icon: Bell },
          { k: "progreso", label: "Progreso", icon: LineChartIcon },
          { k: "chat", label: "Chat", icon: MessageCircle },
          { k: "reporte", label: "Reporte", icon: FileDown },
        ].map((t) => (
          <button
            key={t.k}
            onClick={() => setTab(t.k)}
            style={{
              display: "flex", alignItems: "center", gap: 6, padding: "10px 4px", marginRight: 16,
              background: "none", border: "none", cursor: "pointer",
              borderBottom: tab === t.k ? `2px solid ${T.brand}` : "2px solid transparent",
              color: tab === t.k ? T.brand : T.inkSoft, fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 14,
            }}
          >
            <t.icon size={15} /> {t.label}
          </button>
        ))}
      </div>

      {tab === "expediente" && (
        <div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 10, marginBottom: 18 }}>
            <div style={{ fontFamily: "Fraunces, serif", fontSize: 18, fontWeight: 700, color: T.ink }}>
              Evaluación del {new Date().toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" })}
            </div>
            <Button onClick={saveExpediente}>{saved ? <><Check size={15} /> Guardado</> : <><Plus size={15} /> Nueva evaluación</>}</Button>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: narrow ? "1fr" : "2.1fr 1fr", gap: 18, alignItems: "start" }}>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
              <NumberedCard
                numero={1} icon={ClipboardList} titulo="Historia clínica"
                editing={editingCards.has(1)} onToggleEdit={() => toggleEditCard(1)}
                campos={[
                  { key: "edad", label: "Edad", type: "number" },
                  { key: "sexo", label: "Sexo", type: "select", options: ["M", "H"], format: (v) => (v === "H" ? "Masculino" : v === "M" ? "Femenino" : "—") },
                  ...EXPEDIENTE_SECCIONES.find((s) => s.id === "generales").campos,
                ]}
                values={exp}
                onChange={(k, v) => setExp((p) => ({ ...p, [k]: v }))}
                maxFilas={7}
              />

              <div style={{ gridColumn: "1 / -1" }}>
              <Card>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <div style={{ width: 26, height: 26, borderRadius: "50%", background: T.brandSoft, display: "flex", alignItems: "center", justifyContent: "center" }}>
                      <Activity size={13} color={T.brand} />
                    </div>
                    <span style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600 }}>2. Antropometría</span>
                  </div>
                  <button onClick={() => toggleEditCard(2)} style={{ background: "none", border: "none", cursor: "pointer", color: T.brand, fontSize: 12.5, fontWeight: 700 }}>
                    {editingCards.has(2) ? "Guardar" : "Editar"}
                  </button>
                </div>
                <div style={{ display: "flex", gap: 24, flexWrap: "wrap" }}>
                  <div style={{ flex: "1 1 260px", minWidth: 220 }}>
                    {editingCards.has(2) ? (
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
                        <Field label="Peso (kg)"><input style={inputStyle} type="number" value={exp.peso} onChange={(e) => setExp({ ...exp, peso: e.target.value })} /></Field>
                        <Field label="Estatura (cm)"><input style={inputStyle} type="number" value={exp.talla} onChange={(e) => setExp({ ...exp, talla: e.target.value })} /></Field>
                        {EXPEDIENTE_SECCIONES.find((s) => s.id === "antropometria").campos.map((c) => (
                          <Field key={c.key} label={c.label}>
                            <input style={inputStyle} type={c.type === "number" ? "number" : "text"} value={exp[c.key] || ""} onChange={(e) => setExp({ ...exp, [c.key]: e.target.value })} />
                          </Field>
                        ))}
                      </div>
                    ) : (
                      <div style={{ display: "flex", flexDirection: "column", gap: 9, fontSize: 13 }}>
                        <div style={{ display: "flex", justifyContent: "space-between" }}><span style={{ color: T.inkSoft }}>Peso</span><span style={{ fontWeight: 500 }}>{exp.peso ? `${exp.peso} kg` : "—"}</span></div>
                        <div style={{ display: "flex", justifyContent: "space-between" }}><span style={{ color: T.inkSoft }}>Estatura</span><span style={{ fontWeight: 500 }}>{exp.talla ? `${(exp.talla / 100).toFixed(2)} m` : "—"}</span></div>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                          <span style={{ color: T.inkSoft }}>IMC</span>
                          <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
                            <span style={{ fontWeight: 700 }}>{imc || "—"}</span>
                            {imc && imcCategoria(imc) && (
                              <span style={{ fontSize: 10.5, fontWeight: 700, color: imcCategoria(imc).color, background: `${imcCategoria(imc).color}1A`, padding: "1px 7px", borderRadius: 999 }}>
                                {imcCategoria(imc).label}
                              </span>
                            )}
                          </span>
                        </div>
                        {EXPEDIENTE_SECCIONES.find((s) => s.id === "antropometria").campos.map((c) => (
                          <div key={c.key} style={{ display: "flex", justifyContent: "space-between" }}>
                            <span style={{ color: T.inkSoft }}>{c.label.replace(" (cm)", "").replace("Circunferencia de ", "Circ. ")}</span>
                            <span style={{ fontWeight: 500 }}>{exp[c.key] || "—"}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                  {!editingCards.has(2) && (
                    <div style={{ flex: "0 0 auto" }}>
                      <BodySilhouette sexo={exp.sexo} width={200} />
                    </div>
                  )}
                </div>
              </Card>
              </div>

              <NumberedCard
                numero={3} icon={Utensils} titulo="Evaluación nutricional"
                editing={editingCards.has(3)} onToggleEdit={() => toggleEditCard(3)}
                campos={EXPEDIENTE_SECCIONES.find((s) => s.id === "dietetica").campos}
                values={exp} onChange={(k, v) => setExp((p) => ({ ...p, [k]: v }))}
              />

              <NumberedCard
                numero={4} icon={Flame} titulo="Actividad física"
                editing={editingCards.has(4)} onToggleEdit={() => toggleEditCard(4)}
                campos={[{ key: "actividadFisica", label: "Actividad física", type: "textarea" }]}
                values={exp} onChange={(k, v) => setExp((p) => ({ ...p, [k]: v }))}
              />

              <NumberedCard
                numero={5} icon={Moon} titulo="Estilo de vida"
                editing={editingCards.has(5)} onToggleEdit={() => toggleEditCard(5)}
                campos={[
                  { key: "sueno", label: "Horas y calidad de sueño", type: "text" },
                  { key: "nivelEstres", label: "Nivel de estrés", type: "text" },
                  { key: "rutinaLaboral", label: "Rutina laboral/escolar", type: "text" },
                  { key: "presionArterial", label: "Presión arterial", type: "text" },
                ]}
                values={exp} onChange={(k, v) => setExp((p) => ({ ...p, [k]: v }))}
              />

              <NumberedCard
                numero={6} icon={Target} titulo="Objetivos"
                editing={editingCards.has(6)} onToggleEdit={() => toggleEditCard(6)}
                campos={EXPEDIENTE_SECCIONES.find((s) => s.id === "objetivos").campos}
                values={exp} onChange={(k, v) => setExp((p) => ({ ...p, [k]: v }))}
              />

              <div style={{ gridColumn: "1 / -1" }}>
                <NumberedCard
                  numero={7} icon={FlaskConical} titulo="Estudios de laboratorio"
                  editing={editingCards.has(7)} onToggleEdit={() => toggleEditCard(7)}
                  campos={EXPEDIENTE_SECCIONES.find((s) => s.id === "bioquimicos").campos}
                  values={exp} onChange={(k, v) => setExp((p) => ({ ...p, [k]: v }))}
                  maxFilas={4}
                />
              </div>

              <div style={{ gridColumn: "1 / -1" }}>
                <Card style={{ background: T.brandSoft }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <Pencil size={15} color={T.brandDark} />
                      <span style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600 }}>8. Diagnóstico nutricional</span>
                    </div>
                    <button onClick={() => toggleEditCard(8)} style={{ background: "none", border: "none", cursor: "pointer", color: T.brandDark, fontSize: 12.5, fontWeight: 700 }}>
                      {editingCards.has(8) ? "Guardar" : "Editar"}
                    </button>
                  </div>
                  {editingCards.has(8) ? (
                    <textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical", background: "#fff" }} value={exp.diagnostico || ""} onChange={(e) => setExp({ ...exp, diagnostico: e.target.value })} />
                  ) : (
                    <div style={{ fontSize: 13.5, color: T.ink, whiteSpace: "pre-wrap" }}>{exp.diagnostico || "Sin diagnóstico registrado aún."}</div>
                  )}
                </Card>
              </div>

              <div style={{ gridColumn: "1 / -1" }}>
                <Card>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <ClipboardList size={15} color={T.brand} />
                      <span style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600 }}>9. Notas adicionales</span>
                    </div>
                    <button onClick={() => toggleEditCard(9)} style={{ background: "none", border: "none", cursor: "pointer", color: T.brand, fontSize: 12.5, fontWeight: 700 }}>
                      {editingCards.has(9) ? "Guardar" : "Editar"}
                    </button>
                  </div>
                  {editingCards.has(9) ? (
                    <textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={exp.notas || ""} onChange={(e) => setExp({ ...exp, notas: e.target.value })} />
                  ) : (
                    <div style={{ fontSize: 13.5, color: T.ink, whiteSpace: "pre-wrap" }}>{exp.notas || "Sin notas adicionales."}</div>
                  )}
                </Card>
              </div>
            </div>

            {/* Columna derecha: fotos, evolución, acciones rápidas */}
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <Card>
                <div style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600, marginBottom: 12 }}>10. Fotografías de progreso</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 6, marginBottom: 10 }}>
                  {["Frente", "Perfil", "Espalda"].map((angulo) => {
                    const foto = fotosProgreso.find((f) => f.angulo === angulo);
                    const inputId = `foto-${angulo}-${patientUsername}`;
                    return (
                      <div key={angulo} style={{ textAlign: "center" }}>
                        <div style={{ fontSize: 10, color: T.inkSoft, marginBottom: 4 }}>{angulo}</div>
                        <label htmlFor={inputId} style={{ display: "block", cursor: "pointer" }}>
                          {foto ? (
                            <img src={foto.foto} alt={angulo} style={{ width: "100%", aspectRatio: "3/4", objectFit: "cover", borderRadius: 8 }} />
                          ) : (
                            <div style={{ width: "100%", aspectRatio: "3/4", borderRadius: 8, background: T.bg, border: `1px dashed ${T.line}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                              <Camera size={16} color={T.inkSoft} />
                            </div>
                          )}
                        </label>
                        <input id={inputId} type="file" accept="image/*" style={{ display: "none" }} onChange={(e) => subirFotoProgreso(e.target.files?.[0], angulo)} />
                      </div>
                    );
                  })}
                </div>
                {fotosProgreso.length > 0 && (
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 4, marginBottom: 10 }}>
                    {fotosProgreso.slice(0, 6).map((f) => (
                      <div key={f.id} style={{ position: "relative" }}>
                        <img src={f.foto} alt={f.angulo} style={{ width: 34, height: 34, objectFit: "cover", borderRadius: 6 }} title={`${f.angulo} · ${f.fecha}`} />
                        <button onClick={() => eliminarFotoProgreso(f.id)} style={{ position: "absolute", top: -4, right: -4, width: 14, height: 14, borderRadius: "50%", background: T.accent2, border: "1.5px solid #fff", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", padding: 0 }}>
                          <X size={9} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
                <div style={{ fontSize: 11, color: T.inkSoft }}>{subiendoFoto ? "Subiendo…" : "Toca un recuadro para subir una foto."}</div>
              </Card>

              <Card>
                <div style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600, marginBottom: 12 }}>Evolución del paciente</div>
                {(exp.historial || []).length === 0 ? (
                  <div style={{ fontSize: 12.5, color: T.inkSoft }}>Aún no hay evaluaciones guardadas.</div>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
                    {[...exp.historial].slice(-5).reverse().map((h, i, arr) => (
                      <div key={h.fecha} style={{ display: "flex", gap: 10, paddingBottom: i === arr.length - 1 ? 0 : 14, position: "relative" }}>
                        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                          <div style={{ width: 18, height: 18, borderRadius: "50%", background: T.brand, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                            <Check size={11} color="#fff" />
                          </div>
                          {i !== arr.length - 1 && <div style={{ width: 2, flex: 1, background: T.line, marginTop: 2 }} />}
                        </div>
                        <div style={{ paddingBottom: 4 }}>
                          <div style={{ fontSize: 11.5, color: T.inkSoft, fontFamily: "IBM Plex Mono, monospace" }}>{h.fecha}</div>
                          <div style={{ fontSize: 13, fontWeight: 600, color: T.ink }}>{i === arr.length - 1 ? "Evaluación inicial" : `Seguimiento ${arr.length - 1 - i}`}</div>
                          <div style={{ fontSize: 11.5, color: T.inkSoft }}>
                            Peso: {h.peso} kg{h.grasa ? ` · % Grasa: ${h.grasa}%` : ""}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </Card>

              <Card>
                <div style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600, marginBottom: 12 }}>Acciones rápidas</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                  <button onClick={() => setTab("dieta")} style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8, padding: 10, borderRadius: 10, border: `1px solid ${T.line}`, background: T.bg, cursor: "pointer", textAlign: "left" }}>
                    <Apple size={16} color={T.brand} /><span style={{ fontSize: 11, fontWeight: 600, color: T.ink }}>Generar plan alimenticio</span>
                  </button>
                  <button onClick={() => setTab("progreso")} style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8, padding: 10, borderRadius: 10, border: `1px solid ${T.line}`, background: T.bg, cursor: "pointer", textAlign: "left" }}>
                    <LineChartIcon size={16} color={T.brand} /><span style={{ fontSize: 11, fontWeight: 600, color: T.ink }}>Comparar evaluaciones</span>
                  </button>
                  <button onClick={() => setTab("reporte")} style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8, padding: 10, borderRadius: 10, border: `1px solid ${T.line}`, background: T.bg, cursor: "pointer", textAlign: "left" }}>
                    <Printer size={16} color={T.brand} /><span style={{ fontSize: 11, fontWeight: 600, color: T.ink }}>Imprimir evaluación</span>
                  </button>
                  <a
                    href={waLink(patientUsername, `Hola ${name.split(" ")[0]}, te comparto los resultados de tu evaluación del ${new Date().toLocaleDateString("es-MX")}. 🥗`)}
                    target="_blank" rel="noopener noreferrer"
                    style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8, padding: 10, borderRadius: 10, border: `1px solid ${T.line}`, background: T.bg, cursor: "pointer", textAlign: "left", color: "inherit", textDecoration: "none" }}
                  >
                    <MessageCircle size={16} color="#25D366" /><span style={{ fontSize: 11, fontWeight: 600, color: T.ink }}>Enviar a paciente</span>
                  </a>
                </div>
              </Card>
            </div>
          </div>
        </div>
      )}

      {tab === "antropometria" && (
        <div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 12, marginBottom: 18 }}>
            <div style={{ display: "flex", gap: 4, background: T.bg, borderRadius: 8, padding: 4 }}>
              {[{ k: "mediciones", label: "Mediciones actuales" }, { k: "graficas", label: "Gráficas de evolución" }].map((v) => (
                <button
                  key={v.k}
                  onClick={() => setSubvistaAntro(v.k)}
                  style={{
                    padding: "7px 14px", borderRadius: 6, border: "none", cursor: "pointer",
                    fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 13,
                    background: subvistaAntro === v.k ? T.surface : "transparent",
                    color: subvistaAntro === v.k ? T.brand : T.inkSoft,
                  }}
                >
                  {v.label}
                </button>
              ))}
            </div>
            {subvistaAntro === "mediciones" && (
              <Button onClick={() => { if (editandoMedidas) saveExpediente(); setEditandoMedidas((v) => !v); }}>
                {editandoMedidas ? <><Check size={15} /> Guardar medición</> : <><Plus size={15} /> Nueva medición</>}
              </Button>
            )}
          </div>

          {subvistaAntro === "graficas" ? (
            <Card>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
                <TrendingUp size={16} color={T.brand} />
                <span style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600 }}>Evolución de peso e IMC</span>
              </div>
              <WeightChart historial={exp.historial} talla={exp.talla} />
            </Card>
          ) : (
          <div style={{ display: "grid", gridTemplateColumns: narrow ? "1fr" : "2.3fr 1fr", gap: 18, alignItems: "start" }}>
            <div>
              <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 12, color: T.ink }}>Composición corporal</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(190px, 1fr))", gap: 12, marginBottom: 26 }}>
                <MetricCard icon={Scale} label="Peso" value={exp.peso} unidad="kg" editing={editandoMedidas}
                  onChange={(v) => setExp({ ...exp, peso: v })}
                  subtextoCustom={(() => {
                    const h = exp.historial || [];
                    const anterior = h.length > 1 ? h[h.length - 2] : null;
                    if (!anterior || !exp.peso) return "Sin evaluación anterior";
                    const diff = (Number(exp.peso) - anterior.peso).toFixed(1);
                    return `${diff > 0 ? "↑" : diff < 0 ? "↓" : "→"} ${Math.abs(diff)} kg vs anterior`;
                  })()}
                />
                <MetricCard icon={Ruler} label="Estatura" value={exp.talla ? (exp.talla / 100).toFixed(2) : ""} unidad="m" editing={false}
                  onChange={() => {}} subtextoCustom="—" iconBg={T.brandSoft}
                />
                <MetricCard icon={Activity} label="IMC" value={imc} unidad="" editing={false} onChange={() => {}}
                  subtextoCustom={imc && imcCategoria(imc) ? `Rango: ${imcCategoria(imc).rango}` : "Captura peso y talla"}
                />
                <MetricCard icon={Droplet} label="% Grasa corporal" value={exp.porcentajeGrasa} unidad="%" rangoKey="porcentajeGrasa" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, porcentajeGrasa: v })} />
                <MetricCard icon={Activity} label="Masa muscular" value={exp.masaMuscular} unidad="kg" rangoKey="masaMuscular" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, masaMuscular: v })} />
                <MetricCard icon={Layers} label="Masa grasa" value={exp.masaGrasa} unidad="kg" rangoKey="masaGrasa" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, masaGrasa: v })} />
                <MetricCard icon={Droplet} label="Agua corporal" value={exp.aguaCorporal} unidad="%" rangoKey="aguaCorporal" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, aguaCorporal: v })} />
                <MetricCard icon={Wind} label="Grasa visceral" value={exp.grasaVisceral} unidad="" rangoKey="grasaVisceral" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, grasaVisceral: v })} />
                <MetricCard icon={Flame} label="Tasa metabólica basal" value={exp.tmb} unidad="kcal" rangoKey="tmb" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, tmb: v })} />
                <MetricCard icon={User} label="Edad metabólica" value={exp.edadMetabolica} unidad="años" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, edadMetabolica: v })} subtextoCustom="—" />
                <MetricCard icon={Layers} label="Somatotipo" value={exp.somatotipo} unidad="" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, somatotipo: v })} subtextoCustom="—" />
                <MetricCard icon={Gauge} label="Nivel de grasa" value={exp.nivelGrasa} unidad="" editing={editandoMedidas} onChange={(v) => setExp({ ...exp, nivelGrasa: v })} subtextoCustom="—" />
              </div>

              <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 12, color: T.ink }}>Perímetros</div>
              <div style={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: 20, alignItems: "start" }}>
                <div style={{ paddingTop: 10 }}><BodySilhouette sexo={exp.sexo} width={230} /></div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 24px" }}>
                  {PERIMETROS_CONFIG.map((p) => {
                    const estado = estadoRango(exp[p.key], p.key);
                    const rango = RANGOS_ANTROPOMETRIA[p.key];
                    return (
                      <div key={p.key} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 0", borderBottom: `1px solid ${T.bg}` }}>
                        <span style={{ width: 18, height: 18, borderRadius: "50%", background: T.brand, color: "#fff", fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{p.n}</span>
                        <span style={{ fontSize: 13, color: T.ink, fontWeight: 500, flex: 1 }}>{p.label}</span>
                        {editandoMedidas ? (
                          <input
                            style={{ ...inputStyle, width: 80, padding: "4px 8px", fontSize: 12.5 }}
                            value={exp[p.key] || ""}
                            onChange={(e) => setExp({ ...exp, [p.key]: e.target.value })}
                          />
                        ) : (
                          <>
                            <span style={{ fontSize: 12.5, color: T.ink, width: 62, fontFamily: "IBM Plex Mono, monospace" }}>{exp[p.key] ? `${exp[p.key]} cm` : "—"}</span>
                            <span style={{ fontSize: 11, color: T.inkSoft, width: 78 }}>{rango ? rango.texto : "—"}</span>
                            {estado ? (
                              <span style={{ fontSize: 10, fontWeight: 700, color: estado.color, background: `${estado.color}1A`, padding: "1px 7px", borderRadius: 999, whiteSpace: "nowrap" }}>{estado.label}</span>
                            ) : <span style={{ width: 50 }} />}
                          </>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
              <p style={{ fontSize: 11.5, color: T.inkSoft, marginTop: 16 }}>* Mediciones realizadas con cinta antropométrica estándar. Los rangos son de referencia general y no sustituyen el criterio clínico.</p>

              <Button variant="ghost" onClick={() => setTab("reporte")} style={{ marginTop: 4 }}>
                <Printer size={15} /> Imprimir reporte
              </Button>
            </div>

            {/* Columna derecha */}
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <Card style={{ textAlign: "center" }}>
                <div style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600, marginBottom: 6 }}>Resumen antropométrico</div>
                {(() => {
                  const claves = ["porcentajeGrasa", "masaMuscular", "masaGrasa", "aguaCorporal", "grasaVisceral", "tmb", "circunferenciaCuello", "pecho", "circunferenciaCintura", "abdomen", "circunferenciaCadera", "brazo", "muslo", "pantorrilla", "tobillo"];
                  const evaluadas = claves.filter((k) => exp[k]);
                  const normales = evaluadas.filter((k) => estadoRango(exp[k], k)?.label === "Normal");
                  const score = evaluadas.length ? Math.round((normales.length / evaluadas.length) * 100) : 0;
                  const estadoTxt = evaluadas.length === 0 ? "Sin datos suficientes" : score >= 75 ? "Bueno" : score >= 45 ? "Regular" : "Necesita atención";
                  return (
                    <>
                      <GaugeArc value={score} />
                      <div style={{ fontSize: 11.5, color: T.inkSoft, marginTop: 4 }}>Estado general</div>
                      <div style={{ fontSize: 14, fontWeight: 700, color: T.brand, marginBottom: 8 }}>{estadoTxt}</div>
                      <div style={{ fontSize: 11.5, color: T.inkSoft }}>
                        {evaluadas.length === 0 ? "Captura mediciones para calcular su estado general." : "Basado en cuántas mediciones están dentro del rango de referencia."}
                      </div>
                    </>
                  );
                })()}
              </Card>

              <Card>
                <div style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600, marginBottom: 12 }}>Comparación con evaluación anterior</div>
                {(() => {
                  const h = exp.historial || [];
                  if (h.length < 2) return <div style={{ fontSize: 12.5, color: T.inkSoft }}>Se necesitan al menos 2 evaluaciones guardadas.</div>;
                  const actual = h[h.length - 1], anterior = h[h.length - 2];
                  const filas = [
                    { label: "Peso", unidad: "kg", a: actual.peso, b: anterior.peso },
                    { label: "% Grasa corporal", unidad: "%", a: actual.grasa, b: anterior.grasa },
                  ];
                  return (
                    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                      {filas.filter((f) => f.a != null && f.b != null).map((f) => {
                        const diff = (Number(f.a) - Number(f.b)).toFixed(1);
                        return (
                          <div key={f.label} style={{ display: "flex", justifyContent: "space-between", fontSize: 13 }}>
                            <span style={{ color: T.inkSoft }}>{f.label}</span>
                            <span style={{ fontWeight: 700, color: diff < 0 ? "#3F9142" : diff > 0 ? T.accent2 : T.inkSoft }}>
                              {diff > 0 ? "↑" : diff < 0 ? "↓" : "→"} {Math.abs(diff)} {f.unidad}
                            </span>
                          </div>
                        );
                      })}
                    </div>
                  );
                })()}
                <button onClick={() => setSubvistaAntro("graficas")} style={{ display: "flex", alignItems: "center", gap: 5, background: "none", border: "none", cursor: "pointer", color: T.brand, fontSize: 12, fontWeight: 700, marginTop: 12 }}>
                  <TrendingUp size={13} /> Ver gráfica de evolución
                </button>
              </Card>

              <Card>
                <div style={{ fontFamily: "Fraunces, serif", fontSize: 14.5, fontWeight: 600, marginBottom: 12 }}>Historial de evaluaciones</div>
                {(exp.historial || []).length === 0 ? (
                  <div style={{ fontSize: 12.5, color: T.inkSoft }}>Sin evaluaciones aún.</div>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                    {[...exp.historial].reverse().slice(0, 4).map((h, i) => (
                      <div key={h.fecha} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", fontSize: 12.5 }}>
                        <span style={{ color: T.inkSoft, fontFamily: "IBM Plex Mono, monospace" }}>{h.fecha}</span>
                        <span style={{ color: T.ink, fontWeight: 600 }}>{h.peso} kg</span>
                        {i === 0 && <span style={{ fontSize: 10, fontWeight: 700, color: T.brand, background: T.brandSoft, padding: "1px 7px", borderRadius: 999 }}>Actual</span>}
                      </div>
                    ))}
                  </div>
                )}
              </Card>
            </div>
          </div>
          )}
        </div>
      )}

      {tab === "cuestionario" && (
        <Card style={{ maxWidth: 620 }}>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 6 }}>Cuestionario de admisión</div>
          <p style={{ fontSize: 12.5, color: T.inkSoft, marginTop: 0, marginBottom: 18 }}>
            Puedes llenarlo tú durante la entrevista, o dejarlo listo para cuando el paciente pueda responderlo directamente (próximamente desde su propia app).
          </p>
          {preguntasCuestionario.length === 0 ? (
            <div style={{ fontSize: 13, color: T.inkSoft }}>No hay preguntas configuradas — agrégalas en Configuración → Cuestionario de admisión.</div>
          ) : (
            <>
              {preguntasCuestionario.map((p) => (
                <Field key={p.id} label={p.texto}>
                  <textarea
                    style={{ ...inputStyle, minHeight: 56, resize: "vertical" }}
                    value={respuestasCuestionario[p.id] || ""}
                    onChange={(e) => setRespuestasCuestionario((prev) => ({ ...prev, [p.id]: e.target.value }))}
                  />
                </Field>
              ))}
              <Button onClick={guardarCuestionario}>{savedCuestionario ? <><Check size={15} /> Guardado</> : "Guardar respuestas"}</Button>
            </>
          )}
        </Card>
      )}

      {tab === "bitacora" && (
        <Card style={{ maxWidth: 560 }}>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Bitácora de consultas</div>
          <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
            <textarea
              style={{ ...inputStyle, flex: 1, minHeight: 70, resize: "vertical" }}
              placeholder="Notas de esta consulta: avance, ajustes al plan, indicaciones…"
              value={nuevaNotaBitacora}
              onChange={(e) => setNuevaNotaBitacora(e.target.value)}
            />
          </div>
          <Button onClick={addNotaBitacora} style={{ marginBottom: 20 }}><Plus size={15} /> Agregar nota</Button>

          {bitacora.length === 0 ? (
            <div style={{ fontSize: 13, color: T.inkSoft }}>Aún no hay notas de consulta.</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {bitacora.map((n) => (
                <div key={n.id} style={{ padding: 12, borderRadius: 10, background: T.bg, position: "relative" }}>
                  <div style={{ fontSize: 11, fontFamily: "IBM Plex Mono, monospace", color: T.inkSoft, marginBottom: 4 }}>{n.fecha}</div>
                  <div style={{ fontSize: 14, color: T.ink, whiteSpace: "pre-wrap", paddingRight: 20 }}>{n.texto}</div>
                  <button
                    onClick={() => removeNotaBitacora(n.id)}
                    style={{ position: "absolute", top: 10, right: 10, background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}
                  >
                    <X size={14} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </Card>
      )}

      {tab === "dieta" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
          <Card>
            <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Metas nutricionales</div>
            <Field label="Cargar desde catálogo">
              <select
                style={inputStyle}
                defaultValue=""
                onChange={(e) => {
                  const tpl = plantillas.find((p) => p.id === e.target.value);
                  if (!tpl) return;
                  setDieta({
                    calorias: tpl.calorias,
                    proteinas: tpl.proteinas,
                    carbohidratos: tpl.carbohidratos,
                    grasas: tpl.grasas,
                    comidas: tpl.comidas.map((c) => ({ ...c, id: Date.now() + Math.random() })),
                  });
                  e.target.value = "";
                }}
              >
                <option value="">Elige una plantilla para precargar…</option>
                {plantillas.map((p) => (
                  <option key={p.id} value={p.id}>{p.nombre} ({p.categoria})</option>
                ))}
              </select>
            </Field>
            <Field label="Calorías objetivo (kcal/día)">
              <input style={inputStyle} type="number" value={dieta.calorias} onChange={(e) => setDieta({ ...dieta, calorias: e.target.value })} />
            </Field>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
              <Field label="Prot. %">
                <input style={inputStyle} type="number" value={dieta.proteinas} onChange={(e) => setDieta({ ...dieta, proteinas: Number(e.target.value) })} />
              </Field>
              <Field label="Carb. %">
                <input style={inputStyle} type="number" value={dieta.carbohidratos} onChange={(e) => setDieta({ ...dieta, carbohidratos: Number(e.target.value) })} />
              </Field>
              <Field label="Grasa %">
                <input style={inputStyle} type="number" value={dieta.grasas} onChange={(e) => setDieta({ ...dieta, grasas: Number(e.target.value) })} />
              </Field>
            </div>
            {dieta.proteinas + dieta.carbohidratos + dieta.grasas !== 100 && (
              <div style={{ fontSize: 12, color: T.accent2, marginBottom: 10 }}>
                Los porcentajes suman {dieta.proteinas + dieta.carbohidratos + dieta.grasas}%, no 100%.
              </div>
            )}

            <div style={{ display: "flex", alignItems: "center", gap: 20, margin: "16px 0" }}>
              <PlateRing data={ringData} />
              <div style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: 13 }}>
                {ringData.map((g) => (
                  <div key={g.key} style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 4 }}>
                    <span style={{ width: 8, height: 8, borderRadius: "50%", background: g.color, display: "inline-block" }} />
                    <span style={{ color: T.inkSoft, width: 90, textTransform: "capitalize" }}>{g.label}</span>
                    <span style={{ fontWeight: 600, color: T.ink }}>{grams[g.key]} g</span>
                  </div>
                ))}
              </div>
            </div>
            <Button onClick={saveDieta}>{saved ? <><Check size={15} /> Guardado</> : "Guardar dieta"}</Button>
          </Card>

          <Card>
            <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Alimentos del menú</div>
            <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
              <select style={{ ...inputStyle, width: 110 }} value={nuevoAlimento.comida} onChange={(e) => setNuevoAlimento({ ...nuevoAlimento, comida: e.target.value })}>
                {["Desayuno", "Colación", "Comida", "Cena"].map((c) => <option key={c}>{c}</option>)}
              </select>
              <select style={{ ...inputStyle, width: 120 }} value={nuevoAlimento.grupo} onChange={(e) => setNuevoAlimento({ ...nuevoAlimento, grupo: e.target.value })}>
                {GROUPS.map((g) => <option key={g.key} value={g.key}>{g.label}</option>)}
              </select>
              <input
                style={{ ...inputStyle, flex: 1, minWidth: 120 }}
                placeholder="Ej. Pechuga de pollo"
                value={nuevoAlimento.nombre}
                onChange={(e) => setNuevoAlimento({ ...nuevoAlimento, nombre: e.target.value })}
                onKeyDown={(e) => e.key === "Enter" && addAlimento()}
                list="banco-alimentos-datalist"
              />
              <datalist id="banco-alimentos-datalist">
                {bancoAlimentos.map((a) => <option key={a.id} value={a.nombre} />)}
              </datalist>
              <Button variant="accent" onClick={addAlimento}><Plus size={15} /></Button>
            </div>

            {["Desayuno", "Colación", "Comida", "Cena"].map((comida) => {
              const items = dieta.comidas.filter((c) => c.comida === comida);
              if (items.length === 0) return null;
              return (
                <div key={comida} style={{ marginBottom: 12 }}>
                  <div style={{ fontSize: 12, fontWeight: 700, color: T.brand, textTransform: "uppercase", letterSpacing: 0.3, marginBottom: 6 }}>{comida}</div>
                  {items.map((c) => {
                    const g = GROUPS.find((x) => x.key === c.grupo);
                    return (
                      <div key={c.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "6px 0", borderBottom: `1px solid ${T.bg}` }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                          <span style={{ width: 7, height: 7, borderRadius: "50%", background: g.color, display: "inline-block" }} />
                          <span style={{ fontSize: 14, color: T.ink }}>{c.nombre}</span>
                        </div>
                        <button onClick={() => removeAlimento(c.id)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}>
                          <X size={14} />
                        </button>
                      </div>
                    );
                  })}
                </div>
              );
            })}
            {dieta.comidas.length === 0 && <div style={{ fontSize: 13, color: T.inkSoft }}>Agrega alimentos al menú.</div>}
          </Card>
        </div>
      )}

      {tab === "habitos" && (
        <Card style={{ maxWidth: 480 }}>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Recordatorios de hábitos</div>
          <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
            <input
              style={{ ...inputStyle, flex: 1 }}
              placeholder="Ej. Tomar 2L de agua al día"
              value={nuevoHabito}
              onChange={(e) => setNuevoHabito(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addHabito()}
            />
            <Button variant="accent" onClick={addHabito}><Plus size={15} /></Button>
          </div>
          {habitos.length === 0 ? (
            <div style={{ fontSize: 13, color: T.inkSoft }}>Sin hábitos asignados todavía.</div>
          ) : (
            habitos.map((h) => (
              <div key={h.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 0", borderBottom: `1px solid ${T.bg}` }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <Bell size={14} color={T.accent} />
                  <span style={{ fontSize: 14 }}>{h.texto}</span>
                </div>
                <button onClick={() => removeHabito(h.id)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}>
                  <X size={14} />
                </button>
              </div>
            ))
          )}
        </Card>
      )}

      {tab === "progreso" && (
        <ProgresoView
          title="Progreso"
          historial={exp.historial}
          talla={exp.talla}
          habitos={habitos}
          habitosLog={habitosLog}
        />
      )}

      {tab === "chat" && (
        <ChatView
          storageKey={`chat:${nutriUser.username}:${patientUsername}`}
          role="nutriologo"
          myName={nutriUser.name}
          otherName={name}
        />
      )}

      {tab === "reporte" && (
        <ReporteImprimible patientName={name} nutriName={nutriUser.name} exp={exp} dieta={dieta} demo={!nutriUser.planActivo} />
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Mini calendario mensual
--------------------------------------------------------- */
function MiniCalendar({ citas, mesActual, setMesActual, diaSeleccionado, setDiaSeleccionado }) {
  const year = mesActual.getFullYear();
  const month = mesActual.getMonth();
  const primerDiaSemana = (new Date(year, month, 1).getDay() + 6) % 7; // lunes = 0
  const diasEnMes = new Date(year, month + 1, 0).getDate();
  const hoyStr = new Date().toISOString().slice(0, 10);

  const porDia = {};
  citas.forEach((c) => {
    if (c.estado === "cancelada") return;
    porDia[c.fecha] = (porDia[c.fecha] || 0) + 1;
  });

  const celdas = [];
  for (let i = 0; i < primerDiaSemana; i++) celdas.push(null);
  for (let d = 1; d <= diasEnMes; d++) celdas.push(d);

  const cambiarMes = (delta) => {
    const nuevo = new Date(year, month + delta, 1);
    setMesActual(nuevo);
    setDiaSeleccionado(null);
  };

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
        <button onClick={() => cambiarMes(-1)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft, padding: 4 }}>
          <ChevronRight size={18} style={{ transform: "rotate(180deg)" }} />
        </button>
        <span style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, textTransform: "capitalize" }}>
          {mesActual.toLocaleDateString("es-MX", { month: "long", year: "numeric" })}
        </span>
        <button onClick={() => cambiarMes(1)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft, padding: 4 }}>
          <ChevronRight size={18} />
        </button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4, marginBottom: 4 }}>
        {DIAS_SEMANA.map((d) => (
          <div key={d} style={{ textAlign: "center", fontSize: 11, fontWeight: 700, color: T.inkSoft }}>{d}</div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 4 }}>
        {celdas.map((d, i) => {
          if (!d) return <div key={i} />;
          const fechaStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
          const count = porDia[fechaStr] || 0;
          const esHoy = fechaStr === hoyStr;
          const seleccionado = fechaStr === diaSeleccionado;
          return (
            <button
              key={i}
              onClick={() => setDiaSeleccionado(seleccionado ? null : fechaStr)}
              style={{
                aspectRatio: "1", borderRadius: 8, border: esHoy ? `1.5px solid ${T.brand}` : "1px solid transparent",
                background: seleccionado ? T.brand : count > 0 ? "#EAF2ED" : "transparent",
                color: seleccionado ? "#fff" : T.ink, cursor: "pointer",
                display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
                fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: esHoy ? 700 : 500, position: "relative",
              }}
            >
              {d}
              {count > 0 && (
                <span style={{
                  fontSize: 8.5, marginTop: 1, fontWeight: 700,
                  color: seleccionado ? "#fff" : T.brand,
                }}>
                  {count}
                </span>
              )}
            </button>
          );
        })}
      </div>
    </Card>
  );
}

/* ---------------------------------------------------------
   Nutriólogo: Agenda / citas
--------------------------------------------------------- */
function AgendaNutriologo({ user }) {
  const [citas, setCitas] = useState([]);
  const [patients, setPatients] = useState([]);
  const [form, setForm] = useState({ patientUsername: "", fecha: "", hora: "", motivo: "", monto: "" });
  const [error, setError] = useState("");
  const [vista, setVista] = useState("lista"); // lista | calendario
  const [mesActual, setMesActual] = useState(new Date());
  const [diaSeleccionado, setDiaSeleccionado] = useState(null);
  const [plantillas, setPlantillas] = useState(PLANTILLAS_WHATSAPP_DEFAULT);

  const load = useCallback(async () => {
    const list = (await sGet(`citas:${user.username}`)) || [];
    setCitas(list.sort((a, b) => (a.fecha + a.hora).localeCompare(b.fecha + b.hora)));
    const pats = (await sGet(`patients:${user.username}`)) || [];
    const users = (await sGet("users")) || {};
    setPatients(pats.map((u) => ({ username: u, name: users[u]?.name || u })));
    const plant = await sGet(`plantillasWhatsapp:${user.username}`);
    setPlantillas({ ...PLANTILLAS_WHATSAPP_DEFAULT, ...(plant || {}) });
  }, [user.username]);

  useEffect(() => { load(); }, [load]);

  const hayConflicto = (fecha, hora, ignorarId) =>
    citas.some((c) => c.id !== ignorarId && c.fecha === fecha && c.hora === hora && c.estado !== "cancelada");

  const addCita = async () => {
    setError("");
    if (!form.patientUsername || !form.fecha || !form.hora) return;
    if (hayConflicto(form.fecha, form.hora)) {
      setError("Ya tienes otra cita confirmada o pendiente en ese mismo horario.");
      return;
    }
    const patientName = patients.find((p) => p.username === form.patientUsername)?.name || form.patientUsername;
    const nueva = { id: Date.now(), ...form, patientName, estado: "confirmada", creadoPor: "nutriologo", pagado: false };
    const updated = [...citas, nueva];
    setCitas(updated);
    setForm({ patientUsername: "", fecha: "", hora: "", motivo: "", monto: "" });
    await sSet(`citas:${user.username}`, updated);
  };

  const setEstado = async (id, estado, cita) => {
    setError("");
    if (estado === "confirmada" && cita && hayConflicto(cita.fecha, cita.hora, id)) {
      setError(`Ojo: ya tienes otra cita en ${cita.fecha} a las ${cita.hora}. Confírmala solo si de verdad quieres empalmarlas.`);
    }
    const updated = citas.map((c) => (c.id === id ? { ...c, estado } : c));
    setCitas(updated);
    await sSet(`citas:${user.username}`, updated);
  };

  const togglePagado = async (id) => {
    const updated = citas.map((c) => (c.id === id ? { ...c, pagado: !c.pagado } : c));
    setCitas(updated);
    await sSet(`citas:${user.username}`, updated);
  };

  const removeCita = async (id) => {
    const updated = citas.filter((c) => c.id !== id);
    setCitas(updated);
    await sSet(`citas:${user.username}`, updated);
  };

  const badgeColor = { confirmada: T.brand, pendiente: T.accent, cancelada: T.accent2 };

  const mensajeCita = (c) => interpolarPlantilla(plantillas.recordatorioCita, {
    nombre: (c.patientName || "").split(" ")[0],
    fecha: c.fecha, hora: c.hora,
    motivo: c.motivo ? ` (${c.motivo})` : "",
    nutriologo: user.name,
  });

  const citasVisibles = vista === "calendario" && diaSeleccionado
    ? citas.filter((c) => c.fecha === diaSeleccionado)
    : citas;

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
        <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: 0, color: T.ink }}>Agenda</h1>
        <div style={{ display: "flex", gap: 4, background: T.bg, borderRadius: 8, padding: 4 }}>
          {[{ k: "lista", label: "Lista" }, { k: "calendario", label: "Calendario" }].map((v) => (
            <button
              key={v.k}
              onClick={() => setVista(v.k)}
              style={{
                padding: "6px 14px", borderRadius: 6, border: "none", cursor: "pointer",
                fontFamily: "Inter, sans-serif", fontWeight: 600, fontSize: 13,
                background: vista === v.k ? T.surface : "transparent",
                color: vista === v.k ? T.brand : T.inkSoft,
              }}
            >
              {v.label}
            </button>
          ))}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1.4fr", gap: 20 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <Card>
            <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Agendar cita</div>
            <Field label="Paciente">
              <select style={inputStyle} value={form.patientUsername} onChange={(e) => setForm({ ...form, patientUsername: e.target.value })}>
                <option value="">Selecciona un paciente</option>
                {patients.map((p) => <option key={p.username} value={p.username}>{p.name}</option>)}
              </select>
            </Field>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <Field label="Fecha">
                <input style={inputStyle} type="date" value={form.fecha} onChange={(e) => setForm({ ...form, fecha: e.target.value })} />
              </Field>
              <Field label="Hora">
                <input style={inputStyle} type="time" value={form.hora} onChange={(e) => setForm({ ...form, hora: e.target.value })} />
              </Field>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <Field label="Motivo (opcional)">
                <input style={inputStyle} value={form.motivo} onChange={(e) => setForm({ ...form, motivo: e.target.value })} placeholder="Seguimiento mensual" />
              </Field>
              <Field label="Monto (opcional)">
                <input style={inputStyle} type="number" value={form.monto} onChange={(e) => setForm({ ...form, monto: e.target.value })} placeholder="$" />
              </Field>
            </div>
            <Button onClick={addCita} disabled={patients.length === 0}><Plus size={15} /> Agendar</Button>
            {error && <div style={{ fontSize: 12.5, color: T.accent2, marginTop: 8, fontWeight: 500 }}>{error}</div>}
            {patients.length === 0 && <div style={{ fontSize: 12, color: T.inkSoft, marginTop: 8 }}>Necesitas al menos un paciente registrado.</div>}
          </Card>

          {vista === "calendario" && (
            <MiniCalendar citas={citas} mesActual={mesActual} setMesActual={setMesActual} diaSeleccionado={diaSeleccionado} setDiaSeleccionado={setDiaSeleccionado} />
          )}
        </div>

        <Card>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>
            {vista === "calendario" && diaSeleccionado ? `Citas del ${diaSeleccionado}` : "Próximas citas"}
          </div>
          {citasVisibles.length === 0 ? (
            <div style={{ fontSize: 13, color: T.inkSoft }}>
              {vista === "calendario" && diaSeleccionado ? "Sin citas ese día." : "No tienes citas registradas."}
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {citasVisibles.map((c) => (
                <div key={c.id} style={{ padding: "10px 12px", borderRadius: 10, background: T.bg }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <div>
                      <div style={{ fontSize: 14, fontWeight: 600, color: T.ink }}>{c.patientName}</div>
                      <div style={{ fontSize: 12, color: T.inkSoft, fontFamily: "IBM Plex Mono, monospace" }}>{c.fecha} · {c.hora} {c.motivo && `· ${c.motivo}`}</div>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <span style={{ fontSize: 11, fontWeight: 700, color: badgeColor[c.estado], textTransform: "uppercase" }}>{c.estado}</span>
                      {c.estado === "pendiente" && (
                        <button onClick={() => setEstado(c.id, "confirmada", c)} style={{ background: "none", border: "none", cursor: "pointer", color: T.brand }}><Check size={15} /></button>
                      )}
                      <a
                        href={waLink(c.patientUsername, mensajeCita(c))}
                        target="_blank" rel="noopener noreferrer"
                        title="Enviar recordatorio por WhatsApp"
                        style={{ display: "flex", color: "#25D366" }}
                      >
                        <MessageCircle size={16} />
                      </a>
                      <button onClick={() => removeCita(c.id)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}><Trash2 size={14} /></button>
                    </div>
                  </div>
                  {(c.monto || c.monto === 0) && c.monto !== "" && (
                    <button
                      onClick={() => togglePagado(c.id)}
                      style={{
                        marginTop: 8, display: "inline-flex", alignItems: "center", gap: 5, padding: "3px 10px", borderRadius: 999,
                        border: "none", cursor: "pointer", fontSize: 11.5, fontWeight: 700,
                        background: c.pagado ? "#EAF2ED" : "#FDF1E0",
                        color: c.pagado ? T.brand : T.accent,
                      }}
                    >
                      {c.pagado ? <Check size={11} /> : null} ${c.monto} {c.pagado ? "Pagado" : "Pendiente de pago"}
                    </button>
                  )}
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Nutriólogo: Catálogo de dietas prediseñadas
--------------------------------------------------------- */
function CatalogoNutriologo({ user }) {
  const [plantillas, setPlantillas] = useState(PLANTILLAS_DEFAULT);
  const [form, setForm] = useState({ nombre: "", categoria: "", calorias: 2000, proteinas: 30, carbohidratos: 40, grasas: 30 });
  const [alimento, setAlimento] = useState({ comida: "Desayuno", grupo: "verduras", nombre: "" });
  const [comidas, setComidas] = useState([]);

  const load = useCallback(async () => {
    const cat = await sGet(`dietasPredisenadas:${user.username}`);
    if (cat && cat.length) setPlantillas(cat);
    else await sSet(`dietasPredisenadas:${user.username}`, PLANTILLAS_DEFAULT);
  }, [user.username]);
  useEffect(() => { load(); }, [load]);

  const addAlimento = () => {
    if (!alimento.nombre.trim()) return;
    setComidas([...comidas, { ...alimento }]);
    setAlimento({ ...alimento, nombre: "" });
  };

  const crearPlantilla = async () => {
    if (!form.nombre.trim() || comidas.length === 0) return;
    const nueva = { id: `tpl-${Date.now()}`, ...form, comidas };
    const updated = [...plantillas, nueva];
    setPlantillas(updated);
    await sSet(`dietasPredisenadas:${user.username}`, updated);
    setForm({ nombre: "", categoria: "", calorias: 2000, proteinas: 30, carbohidratos: 40, grasas: 30 });
    setComidas([]);
  };

  const eliminarPlantilla = async (id) => {
    const updated = plantillas.filter((p) => p.id !== id);
    setPlantillas(updated);
    await sSet(`dietasPredisenadas:${user.username}`, updated);
  };

  return (
    <div>
      <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: "0 0 20px", color: T.ink }}>Catálogo de dietas</h1>
      <p style={{ color: T.inkSoft, marginTop: -14, marginBottom: 20, fontSize: 14 }}>
        Estas plantillas están disponibles para precargar en el dietocálculo de cualquier paciente.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
        <Card>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Nueva plantilla</div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <Field label="Nombre">
              <input style={inputStyle} value={form.nombre} onChange={(e) => setForm({ ...form, nombre: e.target.value })} placeholder="Ej. Dieta cetogénica" />
            </Field>
            <Field label="Categoría">
              <input style={inputStyle} value={form.categoria} onChange={(e) => setForm({ ...form, categoria: e.target.value })} placeholder="Ej. Deportivo" />
            </Field>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 8 }}>
            <Field label="Kcal"><input style={inputStyle} type="number" value={form.calorias} onChange={(e) => setForm({ ...form, calorias: Number(e.target.value) })} /></Field>
            <Field label="Prot %"><input style={inputStyle} type="number" value={form.proteinas} onChange={(e) => setForm({ ...form, proteinas: Number(e.target.value) })} /></Field>
            <Field label="Carb %"><input style={inputStyle} type="number" value={form.carbohidratos} onChange={(e) => setForm({ ...form, carbohidratos: Number(e.target.value) })} /></Field>
            <Field label="Grasa %"><input style={inputStyle} type="number" value={form.grasas} onChange={(e) => setForm({ ...form, grasas: Number(e.target.value) })} /></Field>
          </div>

          <div style={{ fontSize: 12, fontWeight: 600, color: T.inkSoft, textTransform: "uppercase", margin: "12px 0 6px" }}>Alimentos</div>
          <div style={{ display: "flex", gap: 6, marginBottom: 10, flexWrap: "wrap" }}>
            <select style={{ ...inputStyle, width: 100 }} value={alimento.comida} onChange={(e) => setAlimento({ ...alimento, comida: e.target.value })}>
              {["Desayuno", "Colación", "Comida", "Cena"].map((c) => <option key={c}>{c}</option>)}
            </select>
            <select style={{ ...inputStyle, width: 110 }} value={alimento.grupo} onChange={(e) => setAlimento({ ...alimento, grupo: e.target.value })}>
              {GROUPS.map((g) => <option key={g.key} value={g.key}>{g.label}</option>)}
            </select>
            <input style={{ ...inputStyle, flex: 1, minWidth: 100 }} placeholder="Nombre del alimento" value={alimento.nombre} onChange={(e) => setAlimento({ ...alimento, nombre: e.target.value })} onKeyDown={(e) => e.key === "Enter" && addAlimento()} />
            <Button variant="accent" onClick={addAlimento}><Plus size={14} /></Button>
          </div>
          {comidas.length > 0 && (
            <div style={{ marginBottom: 12 }}>
              {comidas.map((c, i) => (
                <div key={i} style={{ fontSize: 13, color: T.ink, padding: "3px 0" }}>• {c.nombre} <span style={{ color: T.inkSoft }}>({c.comida})</span></div>
              ))}
            </div>
          )}
          <Button onClick={crearPlantilla}>Guardar plantilla</Button>
        </Card>

        <Card>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Plantillas disponibles</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {plantillas.map((p) => (
              <div key={p.id} style={{ padding: 12, borderRadius: 10, background: T.bg }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start" }}>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: 14, color: T.ink }}>{p.nombre}</div>
                    <div style={{ fontSize: 12, color: T.inkSoft }}>{p.categoria} · {p.calorias} kcal</div>
                  </div>
                  <button onClick={() => eliminarPlantilla(p.id)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}><Trash2 size={14} /></button>
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Nutriólogo: Recetas
--------------------------------------------------------- */
function Recetas({ user }) {
  const [recetas, setRecetas] = useState([]);
  const [filtro, setFiltro] = useState("");
  const [abierta, setAbierta] = useState(null);
  const [mostrarForm, setMostrarForm] = useState(false);
  const [form, setForm] = useState({ nombre: "", categoria: "", porciones: 1, ingredientes: [], pasos: "" });
  const [nuevoIngrediente, setNuevoIngrediente] = useState("");

  const load = useCallback(async () => {
    setRecetas((await sGet(`recetas:${user.username}`)) || []);
  }, [user.username]);
  useEffect(() => { load(); }, [load]);

  const addIngrediente = () => {
    if (!nuevoIngrediente.trim()) return;
    setForm((f) => ({ ...f, ingredientes: [...f.ingredientes, nuevoIngrediente.trim()] }));
    setNuevoIngrediente("");
  };

  const quitarIngrediente = (i) => {
    setForm((f) => ({ ...f, ingredientes: f.ingredientes.filter((_, idx) => idx !== i) }));
  };

  const guardarReceta = async () => {
    if (!form.nombre.trim() || form.ingredientes.length === 0) return;
    const nueva = { id: Date.now(), ...form };
    const updated = [...recetas, nueva];
    setRecetas(updated);
    await sSet(`recetas:${user.username}`, updated);
    setForm({ nombre: "", categoria: "", porciones: 1, ingredientes: [], pasos: "" });
    setMostrarForm(false);
  };

  const eliminarReceta = async (id) => {
    const updated = recetas.filter((r) => r.id !== id);
    setRecetas(updated);
    await sSet(`recetas:${user.username}`, updated);
    if (abierta === id) setAbierta(null);
  };

  const filtradas = recetas.filter((r) => r.nombre.toLowerCase().includes(filtro.toLowerCase()));

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
        <div>
          <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: 0, color: T.ink }}>Recetas</h1>
          <p style={{ color: T.inkSoft, marginTop: 6, fontSize: 14 }}>Tu recetario personal — inclúyelas como referencia al armar el plan de un paciente.</p>
        </div>
        {!mostrarForm && <Button onClick={() => setMostrarForm(true)}><Plus size={15} /> Nueva receta</Button>}
      </div>

      {mostrarForm && (
        <Card style={{ marginBottom: 20, maxWidth: 560 }}>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Nueva receta</div>
          <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 10 }}>
            <Field label="Nombre">
              <input style={inputStyle} value={form.nombre} onChange={(e) => setForm({ ...form, nombre: e.target.value })} placeholder="Ej. Bowl de quinoa con pollo" />
            </Field>
            <Field label="Categoría">
              <input style={inputStyle} value={form.categoria} onChange={(e) => setForm({ ...form, categoria: e.target.value })} placeholder="Comida" />
            </Field>
            <Field label="Porciones">
              <input style={inputStyle} type="number" min={1} value={form.porciones} onChange={(e) => setForm({ ...form, porciones: Number(e.target.value) })} />
            </Field>
          </div>

          <div style={{ fontSize: 12, fontWeight: 600, color: T.inkSoft, textTransform: "uppercase", margin: "10px 0 6px" }}>Ingredientes</div>
          <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
            <input
              style={{ ...inputStyle, flex: 1 }}
              placeholder="Ej. 1 taza de quinoa cocida"
              value={nuevoIngrediente}
              onChange={(e) => setNuevoIngrediente(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addIngrediente()}
            />
            <Button variant="accent" onClick={addIngrediente}><Plus size={14} /></Button>
          </div>
          {form.ingredientes.length > 0 && (
            <div style={{ marginBottom: 14 }}>
              {form.ingredientes.map((ing, i) => (
                <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 13, padding: "3px 0" }}>
                  <span>• {ing}</span>
                  <button onClick={() => quitarIngrediente(i)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}><X size={12} /></button>
                </div>
              ))}
            </div>
          )}

          <Field label="Preparación">
            <textarea style={{ ...inputStyle, minHeight: 80, resize: "vertical" }} value={form.pasos} onChange={(e) => setForm({ ...form, pasos: e.target.value })} placeholder="Pasos para prepararla…" />
          </Field>

          <div style={{ display: "flex", gap: 8 }}>
            <Button onClick={guardarReceta}>Guardar receta</Button>
            <Button variant="ghost" onClick={() => setMostrarForm(false)}>Cancelar</Button>
          </div>
        </Card>
      )}

      {recetas.length > 0 && (
        <div style={{ marginBottom: 16, maxWidth: 320 }}>
          <input style={inputStyle} placeholder="Buscar receta…" value={filtro} onChange={(e) => setFiltro(e.target.value)} />
        </div>
      )}

      {recetas.length === 0 ? (
        <Card style={{ textAlign: "center", padding: 40 }}>
          <BookOpenCheck size={28} color={T.brandLight} style={{ marginBottom: 10 }} />
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 18, marginBottom: 4 }}>Aún no tienes recetas</div>
          <div style={{ color: T.inkSoft, fontSize: 14 }}>Agrega tu primera receta con el botón de arriba.</div>
        </Card>
      ) : (
        <div style={{ display: "grid", gap: 10, gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))" }}>
          {filtradas.map((r) => (
            <Card key={r.id} style={{ cursor: "pointer" }} onClick={() => setAbierta(abierta === r.id ? null : r.id)}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div>
                  <div style={{ fontWeight: 600, fontSize: 15, color: T.ink }}>{r.nombre}</div>
                  <div style={{ fontSize: 12, color: T.inkSoft }}>{r.categoria || "Sin categoría"} · {r.porciones} porción(es)</div>
                </div>
                <button onClick={(e) => { e.stopPropagation(); eliminarReceta(r.id); }} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}>
                  <Trash2 size={14} />
                </button>
              </div>
              {abierta === r.id && (
                <div style={{ marginTop: 12, paddingTop: 12, borderTop: `1px solid ${T.line}` }}>
                  <div style={{ fontSize: 11, fontWeight: 700, color: T.inkSoft, textTransform: "uppercase", marginBottom: 4 }}>Ingredientes</div>
                  {r.ingredientes.map((ing, i) => (
                    <div key={i} style={{ fontSize: 13, color: T.ink, padding: "2px 0" }}>• {ing}</div>
                  ))}
                  {r.pasos && (
                    <>
                      <div style={{ fontSize: 11, fontWeight: 700, color: T.inkSoft, textTransform: "uppercase", margin: "10px 0 4px" }}>Preparación</div>
                      <div style={{ fontSize: 13, color: T.ink, whiteSpace: "pre-wrap" }}>{r.pasos}</div>
                    </>
                  )}
                </div>
              )}
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   Nutriólogo: Mis Alimentos (banco reutilizable)
--------------------------------------------------------- */
function MisAlimentos({ user }) {
  const [alimentos, setAlimentos] = useState([]);
  const [nuevo, setNuevo] = useState({ nombre: "", grupo: "verduras" });
  const [filtro, setFiltro] = useState("");

  const load = useCallback(async () => {
    setAlimentos((await sGet(`alimentos:${user.username}`)) || []);
  }, [user.username]);
  useEffect(() => { load(); }, [load]);

  const agregar = async () => {
    if (!nuevo.nombre.trim()) return;
    if (alimentos.some((a) => a.nombre.toLowerCase() === nuevo.nombre.trim().toLowerCase())) {
      setNuevo({ ...nuevo, nombre: "" });
      return;
    }
    const updated = [...alimentos, { id: Date.now(), nombre: nuevo.nombre.trim(), grupo: nuevo.grupo }];
    setAlimentos(updated);
    setNuevo({ ...nuevo, nombre: "" });
    await sSet(`alimentos:${user.username}`, updated);
  };

  const eliminar = async (id) => {
    const updated = alimentos.filter((a) => a.id !== id);
    setAlimentos(updated);
    await sSet(`alimentos:${user.username}`, updated);
  };

  const filtrados = alimentos.filter((a) => a.nombre.toLowerCase().includes(filtro.toLowerCase()));

  return (
    <div>
      <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: "0 0 6px", color: T.ink }}>Mis alimentos</h1>
      <p style={{ color: T.inkSoft, marginTop: 0, marginBottom: 20, fontSize: 14 }}>
        Tu banco personal de alimentos — aparecen como sugerencias al armar el menú de cualquier paciente.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1.3fr", gap: 20 }}>
        <Card>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 16, fontWeight: 600, marginBottom: 14 }}>Agregar alimento</div>
          <Field label="Nombre">
            <input
              style={inputStyle}
              value={nuevo.nombre}
              onChange={(e) => setNuevo({ ...nuevo, nombre: e.target.value })}
              onKeyDown={(e) => e.key === "Enter" && agregar()}
              placeholder="Ej. Pechuga de pollo"
            />
          </Field>
          <Field label="Grupo">
            <select style={inputStyle} value={nuevo.grupo} onChange={(e) => setNuevo({ ...nuevo, grupo: e.target.value })}>
              {GROUPS.map((g) => <option key={g.key} value={g.key}>{g.label}</option>)}
            </select>
          </Field>
          <Button onClick={agregar}><Plus size={15} /> Agregar</Button>
        </Card>

        <Card>
          <Field label="Buscar">
            <input style={inputStyle} value={filtro} onChange={(e) => setFiltro(e.target.value)} placeholder="Filtrar por nombre…" />
          </Field>
          {filtrados.length === 0 ? (
            <div style={{ fontSize: 13, color: T.inkSoft }}>
              {alimentos.length === 0 ? "Aún no tienes alimentos guardados. Se van agregando solos cuando arma dietas, o agrégalos aquí." : "Sin resultados."}
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 420, overflowY: "auto" }}>
              {filtrados.map((a) => {
                const g = GROUPS.find((x) => x.key === a.grupo);
                return (
                  <div key={a.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 10px", borderRadius: 8, background: T.bg }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <span style={{ width: 8, height: 8, borderRadius: "50%", background: g?.color || T.brand, display: "inline-block" }} />
                      <span style={{ fontSize: 14, color: T.ink }}>{a.nombre}</span>
                      <span style={{ fontSize: 11, color: T.inkSoft }}>· {g?.label}</span>
                    </div>
                    <button onClick={() => eliminar(a.id)} style={{ background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}><Trash2 size={13} /></button>
                  </div>
                );
              })}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

