/* ---------------------------------------------------------
   Chat
--------------------------------------------------------- */
function ChatView({ storageKey, role, myName, otherName }) {
  const [mensajes, setMensajes] = useState([]);
  const [texto, setTexto] = useState("");
  const bottomRef = useRef(null);

  const load = useCallback(async () => {
    const msgs = (await sGet(storageKey)) || [];
    setMensajes(msgs);
  }, [storageKey]);

  useEffect(() => {
    load();
    const interval = setInterval(load, 4000);
    return () => clearInterval(interval);
  }, [load]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [mensajes.length]);

  const enviar = async () => {
    if (!texto.trim()) return;
    const nuevo = {
      id: Date.now(),
      de: role,
      nombre: myName,
      texto: texto.trim(),
      hora: new Date().toLocaleTimeString("es-MX", { hour: "2-digit", minute: "2-digit" }),
    };
    const actuales = (await sGet(storageKey)) || [];
    const updated = [...actuales, nuevo];
    setMensajes(updated);
    setTexto("");
    await sSet(storageKey, updated);
  };

  return (
    <div>
      <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: "0 0 20px", color: T.ink }}>
        Chat con {otherName}
      </h1>
      <Card style={{ display: "flex", flexDirection: "column", height: 440, padding: 0, overflow: "hidden" }}>
        <div style={{ flex: 1, overflowY: "auto", padding: 16, display: "flex", flexDirection: "column", gap: 8 }}>
          {mensajes.length === 0 ? (
            <div style={{ margin: "auto", color: T.inkSoft, fontSize: 13, textAlign: "center" }}>
              <MessageCircle size={24} color={T.brandLight} style={{ marginBottom: 8 }} /><br />
              Aún no hay mensajes. Escribe el primero.
            </div>
          ) : (
            mensajes.map((m) => {
              const mio = m.de === role;
              return (
                <div key={m.id} style={{ display: "flex", justifyContent: mio ? "flex-end" : "flex-start" }}>
                  <div style={{
                    maxWidth: "72%", padding: "8px 12px", borderRadius: mio ? "12px 12px 2px 12px" : "12px 12px 12px 2px",
                    background: mio ? T.brand : T.bg, color: mio ? "#fff" : T.ink, fontSize: 14,
                  }}>
                    {m.texto}
                    <div style={{ fontSize: 10, opacity: 0.7, marginTop: 3, fontFamily: "IBM Plex Mono, monospace" }}>{m.hora}</div>
                  </div>
                </div>
              );
            })
          )}
          <div ref={bottomRef} />
        </div>
        <div style={{ display: "flex", gap: 8, padding: 12, borderTop: `1px solid ${T.line}` }}>
          <input
            style={{ ...inputStyle, flex: 1 }}
            placeholder="Escribe un mensaje…"
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && enviar()}
          />
          <Button onClick={enviar}><Send size={15} /></Button>
        </div>
      </Card>
    </div>
  );
}

/* ---------------------------------------------------------
   Reporte imprimible / PDF
--------------------------------------------------------- */
function ReporteImprimible({ patientName, nutriName, exp, dieta, demo }) {
  const imc = exp?.peso && exp?.talla ? (exp.peso / ((exp.talla / 100) ** 2)).toFixed(1) : "—";
  const imcCat = exp?.peso && exp?.talla ? imcCategoria(imc) : null;
  const hoy = new Date().toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" });
  return (
    <div>
      <div className="no-print" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <h1 style={{ fontFamily: "Fraunces, serif", fontSize: 28, margin: 0, color: T.ink }}>Reporte</h1>
        <Button onClick={() => window.print()}><Printer size={15} /> Imprimir / Guardar PDF</Button>
      </div>

      <div id="report-print-area" style={{ position: "relative" }}>
        {demo && (
          <div style={{
            position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center",
            pointerEvents: "none", zIndex: 5, overflow: "hidden",
          }}>
            <span style={{
              transform: "rotate(-32deg)", fontSize: 46, fontWeight: 800, color: "rgba(200,60,80,0.16)",
              fontFamily: "Inter, sans-serif", whiteSpace: "nowrap", letterSpacing: 2,
            }}>
              VERSIÓN DEMO · NutryEasy
            </span>
          </div>
        )}
        <Card style={{ maxWidth: 680, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
            <img src={LOGO_ICONO} alt="NutryEasy" style={{ width: 22, height: 22, objectFit: "contain" }} />
            <span style={{ fontFamily: "Fraunces, serif", fontSize: 20, fontWeight: 600 }}>NutryEasy</span>
          </div>
          <div style={{ fontSize: 12, color: T.inkSoft, marginBottom: 20 }}>Reporte generado el {hoy}{nutriName ? ` · Nutriólogo: ${nutriName}` : ""}</div>

          <div style={{ fontSize: 13, fontWeight: 700, color: T.inkSoft, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Paciente</div>
          <div style={{ fontSize: 18, fontFamily: "Fraunces, serif", marginBottom: 16 }}>{patientName}</div>

          {exp && (
            <>
              <div style={{ fontSize: 13, fontWeight: 700, color: T.inkSoft, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Expediente</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 10, marginBottom: 12, fontFamily: "IBM Plex Mono, monospace", fontSize: 13 }}>
                <div><div style={{ color: T.inkSoft, fontSize: 11 }}>Edad</div>{exp.edad || "—"}</div>
                <div><div style={{ color: T.inkSoft, fontSize: 11 }}>Peso</div>{exp.peso ? `${exp.peso} kg` : "—"}</div>
                <div><div style={{ color: T.inkSoft, fontSize: 11 }}>Talla</div>{exp.talla ? `${exp.talla} cm` : "—"}</div>
                <div><div style={{ color: T.inkSoft, fontSize: 11 }}>IMC</div>{imc}{imcCat ? <span style={{ color: imcCat.color, fontWeight: 700 }}> · {imcCat.label}</span> : ""}</div>
              </div>
              {exp.notas && (
                <div style={{ fontSize: 13, color: T.ink, background: T.bg, padding: 10, borderRadius: 8, marginBottom: 16 }}>{exp.notas}</div>
              )}
            </>
          )}

          {dieta && (
            <>
              <div style={{ fontSize: 13, fontWeight: 700, color: T.inkSoft, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>Plan de alimentación</div>
              <div style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: 13, marginBottom: 14 }}>
                {dieta.calorias} kcal/día · Prot {dieta.proteinas}% · Carb {dieta.carbohidratos}% · Grasa {dieta.grasas}%
              </div>
              {["Desayuno", "Colación", "Comida", "Cena"].map((comida) => {
                const items = (dieta.comidas || []).filter((c) => c.comida === comida);
                if (items.length === 0) return null;
                return (
                  <div key={comida} style={{ marginBottom: 10 }}>
                    <div style={{ fontSize: 12, fontWeight: 700, color: T.brand, textTransform: "uppercase" }}>{comida}</div>
                    {items.map((c, i) => <div key={i} style={{ fontSize: 13, padding: "2px 0" }}>• {c.nombre}</div>)}
                  </div>
                );
              })}
            </>
          )}
        </Card>
      </div>
    </div>
  );
}

