function HomeDashboard({ user, onNavigate }) {
  const narrow = useIsNarrow(1180);
  const hoy = new Date().toLocaleDateString("es-MX", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  const [proximasCitas, setProximasCitas] = useState([]);
  const [plantillas, setPlantillas] = useState(PLANTILLAS_WHATSAPP_DEFAULT);
  const [kpis, setKpis] = useState({ activos: 0, hoy: 0, planes: 0, ingresosMes: 0, pendientes: 0 });
  const [deltas, setDeltas] = useState(null);

  const [pacientes, setPacientes] = useState([]);
  const [busquedaMini, setBusquedaMini] = useState("");
  const [seleccionado, setSeleccionado] = useState(null);
  const [datosSel, setDatosSel] = useState(null);
  const [cargandoSel, setCargandoSel] = useState(false);
  const [notas, setNotas] = useState([]);
  const [nuevaNota, setNuevaNota] = useState("");
  const [mostrarFormNota, setMostrarFormNota] = useState(false);

  useEffect(() => {
    (async () => {
      const citas = (await sGet(`citas:${user.username}`)) || [];
      const hoyStr = new Date().toISOString().slice(0, 10);
      const en7dias = new Date();
      en7dias.setDate(en7dias.getDate() + 7);
      const limiteStr = en7dias.toISOString().slice(0, 10);
      const proximas = citas
        .filter((c) => c.estado !== "cancelada" && c.fecha >= hoyStr && c.fecha <= limiteStr)
        .sort((a, b) => (a.fecha + a.hora).localeCompare(b.fecha + b.hora))
        .slice(0, 4);
      setProximasCitas(proximas);
      const plant = await sGet(`plantillasWhatsapp:${user.username}`);
      setPlantillas({ ...PLANTILLAS_WHATSAPP_DEFAULT, ...(plant || {}) });

      const list = (await sGet(`patients:${user.username}`)) || [];
      const users = (await sGet("users")) || {};
      const listaPacientes = list.map((u) => ({ username: u, name: users[u]?.name || u, activo: users[u]?.activo !== false })).reverse();
      setPacientes(listaPacientes);
      if (listaPacientes.length > 0) setSeleccionado(listaPacientes[0].username);

      const activos = list.filter((u) => users[u]?.activo !== false).length;
      const pendientes = list.length - activos;
      const citasHoy = citas.filter((c) => c.fecha === hoyStr && c.estado !== "cancelada").length;
      const hoyDate = new Date();
      const ingresosMes = citas
        .filter((c) => {
          const f = new Date(c.fecha);
          return f.getMonth() === hoyDate.getMonth() && f.getFullYear() === hoyDate.getFullYear() && c.pagado;
        })
        .reduce((s, c) => s + (Number(c.monto) || 0), 0);
      let planes = 0;
      for (const u of list) {
        const d = await sGet(`dieta:${u}`);
        if (d?.comidas?.length) planes++;
      }
      setKpis({ activos, hoy: citasHoy, planes, ingresosMes, pendientes });

      // Snapshot mensual para poder comparar "vs mes anterior" con datos reales
      const snapKey = `metricasSnapshot:${user.username}`;
      const snap = (await sGet(snapKey)) || {};
      const mesActualKey = new Date().toISOString().slice(0, 7);
      snap[mesActualKey] = { activos, planes, ingresosMes };
      await sSet(snapKey, snap);
      const mesAnteriorDate = new Date();
      mesAnteriorDate.setMonth(mesAnteriorDate.getMonth() - 1);
      const anterior = snap[mesAnteriorDate.toISOString().slice(0, 7)] || null;
      setDeltas(anterior ? {
        activos: calcDelta(activos, anterior.activos),
        planes: calcDelta(planes, anterior.planes),
        ingresosMes: calcDelta(ingresosMes, anterior.ingresosMes),
      } : null);

      setNotas((await sGet(`notasRapidas:${user.username}`)) || []);
    })();
  }, [user.username]);

  const agregarNota = async () => {
    if (!nuevaNota.trim()) return;
    const entry = {
      id: Date.now(), texto: nuevaNota.trim(),
      fecha: new Date().toLocaleDateString("es-MX", { day: "numeric", month: "short", year: "numeric" }),
    };
    const updated = [entry, ...notas];
    setNotas(updated);
    setNuevaNota("");
    setMostrarFormNota(false);
    await sSet(`notasRapidas:${user.username}`, updated);
  };

  const quitarNota = async (id) => {
    const updated = notas.filter((n) => n.id !== id);
    setNotas(updated);
    await sSet(`notasRapidas:${user.username}`, updated);
  };

  useEffect(() => {
    if (!seleccionado) { setDatosSel(null); return; }
    (async () => {
      setCargandoSel(true);
      const exp = await sGet(`expediente:${user.username}:${seleccionado}`);
      const dieta = await sGet(`dieta:${seleccionado}`);
      const habitos = (await sGet(`habitos:${seleccionado}`)) || [];
      const habitosLog = (await sGet(`habitosLog:${seleccionado}`)) || {};
      const bitacora = (await sGet(`bitacora:${user.username}:${seleccionado}`)) || [];
      setDatosSel({ exp: exp || {}, dieta, habitos, habitosLog, bitacora });
      setCargandoSel(false);
    })();
  }, [seleccionado, user.username]);

  const mensajeCita = (c) => interpolarPlantilla(plantillas.recordatorioCita, {
    nombre: (c.patientName || "").split(" ")[0],
    fecha: c.fecha, hora: c.hora,
    motivo: c.motivo ? ` (${c.motivo})` : "",
    nutriologo: user.name,
  });

  const kpiCards = [
    { label: "Pacientes activos", value: kpis.activos, icon: Users, color: T.brand, delta: deltas?.activos },
    { label: "Consultas hoy", value: kpis.hoy, icon: CalendarDays, color: T.accent, link: "agenda", linkLabel: "Ver agenda" },
    { label: "Planes alimenticios", value: kpis.planes, icon: ClipboardList, color: "#4C8C5E", delta: deltas?.planes },
    { label: "Ingresos del mes", value: `$${kpis.ingresosMes}`, icon: PieChart, color: "#3F9142", link: "reportes", delta: deltas?.ingresosMes },
    { label: "Pendientes de activar", value: kpis.pendientes, icon: Bell, color: T.accent2, link: "pacientes" },
  ];

  const pacientesFiltrados = pacientes.filter((p) => p.name.toLowerCase().includes(busquedaMini.toLowerCase()));
  const patientSel = pacientes.find((p) => p.username === seleccionado);

  const imcSel = datosSel?.exp?.peso && datosSel?.exp?.talla
    ? (datosSel.exp.peso / ((datosSel.exp.talla / 100) ** 2)).toFixed(1)
    : null;
  const catSel = imcSel ? imcCategoria(imcSel) : null;

  const macroData = datosSel?.dieta
    ? GROUPS.filter((g) => ["proteinas", "carbohidratos", "grasas"].includes(g.key)).map((g) => ({
        ...g, value: { proteinas: datosSel.dieta.proteinas, carbohidratos: datosSel.dieta.carbohidratos, grasas: datosSel.dieta.grasas }[g.key] || 0,
      }))
    : [];

  const adherencia = (() => {
    if (!datosSel?.habitos?.length) return null;
    const dias = ultimosDias(7);
    let total = 0, hechos = 0;
    dias.forEach((f) => {
      total += datosSel.habitos.length;
      hechos += (datosSel.habitosLog[f] || []).length;
    });
    return total > 0 ? Math.round((hechos / total) * 100) : 0;
  })();

  const diasConHabito = (habitoId) => {
    const dias = ultimosDias(7);
    return dias.filter((f) => (datosSel.habitosLog[f] || []).includes(habitoId)).length;
  };

  const accionesRapidas = [
    { icon: CalendarDays, label: "Nueva consulta", onClick: () => onNavigate("agenda") },
    { icon: ClipboardList, label: "Ver expediente", onClick: () => seleccionado && onNavigate("pacientes", seleccionado) },
    { icon: Apple, label: "Nuevo plan alimenticio", onClick: () => seleccionado && onNavigate("pacientes", seleccionado) },
    { icon: MessageCircle, label: "Mensaje a paciente", onClick: () => seleccionado && window.open(waLink(seleccionado, interpolarPlantilla(plantillas.mensajeGeneral, { nombre: patientSel?.name?.split(" ")[0] || "", nutriologo: user.name })), "_blank") },
  ];

  return (
    <div>
      <div style={{ marginBottom: 24 }}>
        <div style={{ fontFamily: "Fraunces, serif", fontSize: 26, fontWeight: 700, color: T.ink }}>
          ¡Hola, {user.name.split(" ")[0]}! 👋
        </div>
        <div style={{ color: T.inkSoft, fontSize: 14, marginTop: 2 }}>Aquí tienes el resumen de tu consultorio · <span style={{ textTransform: "capitalize" }}>{hoy}</span></div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 12, marginBottom: 24 }}>
        {kpiCards.map((k) => (
          <Card
            key={k.label}
            style={{ cursor: k.link ? "pointer" : "default", display: "flex", alignItems: "center", gap: 14 }}
            onClick={k.link ? () => onNavigate(k.link) : undefined}
          >
            <div style={{ width: 52, height: 52, borderRadius: "50%", background: `${k.color}1F`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
              <k.icon size={22} color={k.color} />
            </div>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 12.5, color: T.inkSoft, marginBottom: 2 }}>{k.label}</div>
              <div style={{ fontFamily: "IBM Plex Mono, monospace", fontSize: 22, fontWeight: 700, color: T.ink, lineHeight: 1.1 }}>{k.value}</div>
              {k.linkLabel ? (
                <div style={{ fontSize: 11.5, fontWeight: 700, color: T.brand, marginTop: 2 }}>{k.linkLabel}</div>
              ) : k.delta !== undefined && k.delta !== null && k.delta !== 0 ? (
                <div style={{ fontSize: 11.5, fontWeight: 700, color: k.delta > 0 ? "#3F9142" : T.accent2, marginTop: 2, display: "flex", alignItems: "center", gap: 2 }}>
                  {k.delta > 0 ? "↑" : "↓"} {Math.abs(k.delta)}% vs mes anterior
                </div>
              ) : k.delta === 0 ? (
                <div style={{ fontSize: 11.5, color: T.inkSoft, marginTop: 2 }}>Igual que el mes anterior</div>
              ) : null}
            </div>
          </Card>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: narrow ? "1fr" : "260px 1fr 260px", gap: 16, alignItems: "start" }}>
        {/* Columna izquierda: pacientes recientes */}
        <Card style={{ padding: 16 }}>
          <div style={{ fontFamily: "Fraunces, serif", fontSize: 15, fontWeight: 600, marginBottom: 10 }}>Pacientes recientes</div>
          <input
            style={{ ...inputStyle, fontSize: 13, marginBottom: 10 }}
            placeholder="Buscar paciente…"
            value={busquedaMini}
            onChange={(e) => setBusquedaMini(e.target.value)}
          />
          {pacientesFiltrados.length === 0 ? (
            <div style={{ fontSize: 12.5, color: T.inkSoft }}>Sin pacientes aún.</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 3, maxHeight: 420, overflowY: "auto" }}>
              {pacientesFiltrados.slice(0, 8).map((p) => (
                <button
                  key={p.username}
                  onClick={() => setSeleccionado(p.username)}
                  style={{
                    display: "flex", alignItems: "center", gap: 8, padding: "8px 8px", borderRadius: 8,
                    border: "none", cursor: "pointer", textAlign: "left",
                    background: seleccionado === p.username ? T.brandSoft : "transparent",
                  }}
                >
                  <PatientAvatar username={p.username} name={p.name} size={28} />
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 12.5, fontWeight: 600, color: T.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.name}</div>
                    <div style={{ fontSize: 10.5, color: T.inkSoft }}>{p.activo ? "Activo" : "Pendiente"}</div>
                  </div>
                </button>
              ))}
            </div>
          )}
          <Button variant="ghost" style={{ width: "100%", justifyContent: "center", marginTop: 10, fontSize: 12.5 }} onClick={() => onNavigate("pacientes")}>
            Ver todos los pacientes
          </Button>
        </Card>

        {/* Columna central: resumen del paciente seleccionado */}
        <div>
          {!seleccionado ? (
            <Card style={{ textAlign: "center", padding: 40 }}>
              <Users size={28} color={T.brandLight} style={{ marginBottom: 10 }} />
              <div style={{ color: T.inkSoft, fontSize: 14 }}>Registra tu primer paciente para ver su resumen aquí.</div>
            </Card>
          ) : (
            <>
              <Card style={{ marginBottom: 14 }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <PatientAvatar username={seleccionado} name={patientSel?.name} size={52} editable />
                    <div>
                      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <span style={{ fontFamily: "Fraunces, serif", fontSize: 18, fontWeight: 700, color: T.ink }}>{patientSel?.name}</span>
                        <span style={{ fontSize: 10.5, fontWeight: 700, padding: "2px 8px", borderRadius: 999, background: patientSel?.activo ? T.brandSoft : "#FDF1E0", color: patientSel?.activo ? T.brandDark : T.accent }}>
                          {patientSel?.activo ? "Paciente activa" : "Pendiente de activación"}
                        </span>
                      </div>
                      <div style={{ fontSize: 12.5, color: T.inkSoft, marginTop: 2 }}>{formatPhone(seleccionado)}</div>
                    </div>
                  </div>
                  <Button variant="ghost" onClick={() => onNavigate("pacientes", seleccionado)} style={{ fontSize: 12.5 }}>
                    Ver expediente completo →
                  </Button>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 10, marginTop: 16, paddingTop: 14, borderTop: `1px solid ${T.line}` }}>
                  <div>
                    <div style={{ fontSize: 10.5, color: T.inkSoft, textTransform: "uppercase", fontWeight: 700 }}>Edad</div>
                    <div style={{ fontSize: 13.5, color: T.ink }}>{datosSel?.exp?.edad || "—"}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 10.5, color: T.inkSoft, textTransform: "uppercase", fontWeight: 700 }}>Sexo</div>
                    <div style={{ fontSize: 13.5, color: T.ink }}>{datosSel?.exp?.sexo === "H" ? "Masculino" : datosSel?.exp?.sexo === "M" ? "Femenino" : "—"}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 10.5, color: T.inkSoft, textTransform: "uppercase", fontWeight: 700 }}>Objetivo</div>
                    <div style={{ fontSize: 13.5, color: T.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{datosSel?.exp?.motivoConsulta || "—"}</div>
                  </div>
                </div>
              </Card>

              {cargandoSel ? (
                <div style={{ color: T.inkSoft, fontSize: 13 }}>Cargando resumen…</div>
              ) : (
                <>
                  <Card style={{ marginBottom: 14 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                      <TrendingUp size={15} color={T.brand} />
                      <span style={{ fontFamily: "Fraunces, serif", fontSize: 15, fontWeight: 600 }}>Progreso general</span>
                      {catSel && (
                        <span style={{ marginLeft: "auto", fontSize: 11, fontWeight: 700, color: catSel.color }}>IMC {imcSel} · {catSel.label}</span>
                      )}
                    </div>
                    <WeightChart historial={datosSel?.exp?.historial} talla={datosSel?.exp?.talla} />
                  </Card>

                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 14 }}>
                    <Card style={{ textAlign: "center" }}>
                      <div style={{ fontSize: 12.5, fontWeight: 600, color: T.ink, marginBottom: 10 }}>Macronutrientes</div>
                      {macroData.length > 0 ? (
                        <>
                          <PlateRing data={macroData} size={90} thickness={11} />
                          <div style={{ fontSize: 10.5, color: T.inkSoft, marginTop: 8 }}>
                            {macroData.map((g) => `${g.label.slice(0, 4)} ${g.value}%`).join(" · ")}
                          </div>
                        </>
                      ) : (
                        <div style={{ fontSize: 12, color: T.inkSoft, padding: "20px 0" }}>Sin dieta asignada.</div>
                      )}
                    </Card>

                    <Card style={{ textAlign: "center" }}>
                      <div style={{ fontSize: 12.5, fontWeight: 600, color: T.ink, marginBottom: 10 }}>Adherencia al plan</div>
                      {adherencia !== null ? (
                        <>
                          <ProgressRing percent={adherencia} size={90} thickness={11} color={adherencia >= 70 ? T.brand : adherencia >= 40 ? T.accent : T.accent2} />
                          <div style={{ fontSize: 11, color: T.inkSoft, marginTop: 8 }}>
                            {adherencia >= 70 ? "Muy buena, ¡sigue así!" : adherencia >= 40 ? "Puede mejorar" : "Necesita seguimiento"}
                          </div>
                        </>
                      ) : (
                        <div style={{ fontSize: 12, color: T.inkSoft, padding: "20px 0" }}>Sin hábitos asignados.</div>
                      )}
                    </Card>

                    <Card>
                      <div style={{ fontSize: 12.5, fontWeight: 600, color: T.ink, marginBottom: 10 }}>Hábitos (7 días)</div>
                      {datosSel?.habitos?.length > 0 ? (
                        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                          {datosSel.habitos.slice(0, 4).map((h) => (
                            <div key={h.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5 }}>
                              <span style={{ color: T.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", maxWidth: 110 }}>{h.texto}</span>
                              <span style={{ color: T.inkSoft, fontFamily: "IBM Plex Mono, monospace", flexShrink: 0 }}>{diasConHabito(h.id)}/7</span>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div style={{ fontSize: 12, color: T.inkSoft }}>Sin hábitos.</div>
                      )}
                    </Card>
                  </div>

                  {datosSel?.bitacora?.length > 0 && (
                    <Card style={{ marginTop: 14, background: "#FDF6E3" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                        <Pencil size={14} color={T.accent} />
                        <span style={{ fontFamily: "Fraunces, serif", fontSize: 14, fontWeight: 600 }}>Última nota de bitácora</span>
                      </div>
                      <div style={{ fontSize: 13, color: T.ink, whiteSpace: "pre-wrap", marginBottom: 6 }}>{datosSel.bitacora[0].texto}</div>
                      <div style={{ fontSize: 11, color: T.inkSoft }}>{datosSel.bitacora[0].fecha} · {user.name}</div>
                    </Card>
                  )}
                </>
              )}
            </>
          )}
        </div>

        {/* Columna derecha: próximas consultas + acciones rápidas */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <Card>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
              <span style={{ fontFamily: "Fraunces, serif", fontSize: 15, fontWeight: 600 }}>Próximas consultas</span>
              <button onClick={() => onNavigate("agenda")} style={{ background: "none", border: "none", cursor: "pointer", color: T.brand, fontSize: 11.5, fontWeight: 700 }}>Ver agenda</button>
            </div>
            {proximasCitas.length === 0 ? (
              <div style={{ fontSize: 12.5, color: T.inkSoft }}>Nada en los próximos 7 días.</div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {proximasCitas.map((c) => (
                  <div key={c.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "7px 8px", borderRadius: 8, background: T.bg }}>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontSize: 12, fontWeight: 600, color: T.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.patientName}</div>
                      <div style={{ fontSize: 10.5, color: T.inkSoft, fontFamily: "IBM Plex Mono, monospace" }}>{c.fecha} · {c.hora}</div>
                    </div>
                    <a href={waLink(c.patientUsername, mensajeCita(c))} target="_blank" rel="noopener noreferrer" style={{ display: "flex", color: "#25D366", flexShrink: 0 }}>
                      <MessageCircle size={15} />
                    </a>
                  </div>
                ))}
              </div>
            )}
          </Card>

          <Card>
            <div style={{ fontFamily: "Fraunces, serif", fontSize: 15, fontWeight: 600, marginBottom: 12 }}>Acciones rápidas</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              {accionesRapidas.map((a) => (
                <button
                  key={a.label}
                  onClick={a.onClick}
                  style={{
                    display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 8, padding: 10,
                    borderRadius: 10, border: `1px solid ${T.line}`, background: T.bg, cursor: "pointer", textAlign: "left",
                  }}
                >
                  <a.icon size={16} color={T.brand} />
                  <span style={{ fontSize: 11, fontWeight: 600, color: T.ink, lineHeight: 1.2 }}>{a.label}</span>
                </button>
              ))}
            </div>
          </Card>

          <Card style={{ background: "#FDF6E3" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
              <span style={{ fontFamily: "Fraunces, serif", fontSize: 15, fontWeight: 600 }}>Notas rápidas</span>
              <button
                onClick={() => setMostrarFormNota((v) => !v)}
                style={{ background: "none", border: "none", cursor: "pointer", color: T.accent }}
                title="Agregar nota"
              >
                <Plus size={16} />
              </button>
            </div>

            {mostrarFormNota && (
              <div style={{ marginBottom: 12 }}>
                <textarea
                  autoFocus
                  style={{ ...inputStyle, minHeight: 60, resize: "vertical", background: "#fff", marginBottom: 6 }}
                  placeholder="Escribe una nota…"
                  value={nuevaNota}
                  onChange={(e) => setNuevaNota(e.target.value)}
                />
                <div style={{ display: "flex", gap: 6 }}>
                  <Button onClick={agregarNota} style={{ padding: "6px 12px", fontSize: 12.5 }}>Guardar</Button>
                  <Button variant="ghost" onClick={() => { setMostrarFormNota(false); setNuevaNota(""); }} style={{ padding: "6px 12px", fontSize: 12.5 }}>Cancelar</Button>
                </div>
              </div>
            )}

            {notas.length === 0 ? (
              !mostrarFormNota && <div style={{ fontSize: 12.5, color: T.inkSoft }}>Sin notas todavía. Usa el "+" para agregar una.</div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 220, overflowY: "auto" }}>
                {notas.map((n) => (
                  <div key={n.id} style={{ position: "relative", padding: "8px 24px 8px 0" }}>
                    <div style={{ fontSize: 12.5, color: T.ink, whiteSpace: "pre-wrap" }}>{n.texto}</div>
                    <div style={{ fontSize: 10.5, color: T.inkSoft, marginTop: 3 }}>{n.fecha} · {user.name.split(" ")[0]}</div>
                    <button
                      onClick={() => quitarNota(n.id)}
                      style={{ position: "absolute", top: 6, right: 0, background: "none", border: "none", cursor: "pointer", color: T.inkSoft }}
                    >
                      <X size={12} />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </Card>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   App root
--------------------------------------------------------- */
export default function App() {
  const [user, setUser] = useState(null);
  const [tab, setTab] = useState(null);
  const [openPatient, setOpenPatient] = useState(null);
  const [busquedaGlobal, setBusquedaGlobal] = useState("");
  const [nuevoPacienteTrigger, setNuevoPacienteTrigger] = useState(0);
  const [pendientesCount, setPendientesCount] = useState(0);
  const [patientTab, setPatientTab] = useState("expediente");

  useEffect(() => {
    if (user) setTab("inicio");
  }, [user]);

  useEffect(() => {
    if (!user) return;
    (async () => {
      const list = (await sGet(`patients:${user.username}`)) || [];
      const users = (await sGet("users")) || {};
      setPendientesCount(list.filter((u) => users[u]?.activo === false).length);
    })();
  }, [user, tab]);

  const nutriTabs = [
    { key: "inicio", label: "Dashboard", icon: Home },
    { key: "pacientes", label: "Pacientes", icon: Users },
    { key: "agenda", label: "Agenda", icon: CalendarDays },
    {
      key: "consulta", label: "Consulta Clínica", icon: ClipboardList,
      children: [
        { key: "evaluaciones", label: "Evaluaciones", patientTab: "expediente" },
        { key: "historia", label: "Historia Clínica", patientTab: "expediente" },
        { key: "antropometria", label: "Antropometría", patientTab: "antropometria" },
        { key: "nutricional", label: "Evaluación Nutricional", patientTab: "expediente" },
        { key: "estilo", label: "Estilo de Vida", patientTab: "expediente" },
        { key: "laboratorio", label: "Estudios de Laboratorio", patientTab: "expediente" },
        { key: "evolucion", label: "Evolución", patientTab: "progreso" },
      ],
    },
    { key: "catalogo", label: "Planes Alimenticios", icon: BookMarked },
    { key: "seguimiento", label: "Seguimiento", icon: LineChartIcon },
    { key: "mensajes", label: "Mensajes", icon: MessageCircle },
    { key: "alimentos", label: "Alimentos", icon: Apple },
    { key: "recetas", label: "Recetas", icon: BookOpenCheck },
    { key: "reportes", label: "Reportes", icon: PieChart },
    { key: "facturacion", label: "Facturación", icon: Receipt },
    { key: "configuracion", label: "Configuración", icon: Settings },
  ];

  return (
    <div style={{ minHeight: "100vh", background: T.bg, fontFamily: "Inter, sans-serif", color: T.ink }}>
      <style>{FONTS}</style>
      {!user ? (
        <AuthScreen onLogin={setUser} />
      ) : estadoPlan(user).expirado ? (
        <PruebaExpirada user={user} onActivado={setUser} onLogout={() => setUser(null)} />
      ) : (
        <Shell
          user={user}
          onLogout={() => { setUser(null); setOpenPatient(null); }}
          tabs={nutriTabs}
          active={tab}
          setActive={(k) => { setTab(k); setOpenPatient(null); }}
          busqueda={busquedaGlobal}
          setBusqueda={setBusquedaGlobal}
          onNuevoPaciente={() => { setTab("pacientes"); setOpenPatient(null); setNuevoPacienteTrigger((n) => n + 1); }}
          pendientesCount={pendientesCount}
          onConsultaClinica={(target) => { setTab("pacientes"); setPatientTab(target); }}
          patientTab={patientTab}
        >
          {tab === "inicio" && <HomeDashboard user={user} onNavigate={(k, patientUsername) => { setTab(k); setOpenPatient(patientUsername || null); }} />}
          {tab === "pacientes" && (
            openPatient
              ? <PatientDetail patientUsername={openPatient} onBack={() => setOpenPatient(null)} nutriUser={user} initialTab={patientTab} onTabChange={setPatientTab} />
              : <PatientList user={user} onOpen={setOpenPatient} busqueda={busquedaGlobal} setBusqueda={setBusquedaGlobal} abrirFormExterno={nuevoPacienteTrigger} />
          )}
          {tab === "agenda" && <AgendaNutriologo user={user} />}
          {tab === "catalogo" && <CatalogoNutriologo user={user} />}
          {tab === "seguimiento" && <SeguimientoView user={user} onAbrirPaciente={(u) => { setTab("pacientes"); setOpenPatient(u); }} />}
          {tab === "mensajes" && <MensajesView user={user} onAbrirPaciente={(u) => { setTab("pacientes"); setOpenPatient(u); setPatientTab("chat"); }} />}
          {tab === "recetas" && <Recetas user={user} />}
          {tab === "alimentos" && <MisAlimentos user={user} />}
          {tab === "reportes" && <ReportesGenerales user={user} />}
          {tab === "facturacion" && <FacturacionView user={user} />}
          {tab === "configuracion" && <ConfiguracionCuenta user={user} onUpdateUser={setUser} />}
        </Shell>
      )}
    </div>
  );
}
